  fish: { name: 'a fish', colours: { '.': ['blue', '#8ecbff'], O: ['orange', '#ff9f1c'], K: ['black', '#2d2350'], Y: ['yellow', '#ffd23f'] },
    rows: ['............', '............', '...OOOO...O.', '..OOYOOO.OO.', '.OKOYOYOOOO.', 'OOOOYOYOOOO.', 'OOOOYOYOOOO.', '.OOOYOYOOOO.', '..OOYOOO.OO.', '...OOOO...O.', '............', '............'] },
