const rdEye = (x, y, r) => `<circle cx="${x}" cy="${y}" r="${r}" ${RD_S}/><circle cx="${x + r * 0.2}" cy="${y + r * 0.1}" r="${r * 0.45}" ${RD_F}/>`;
