const HOME_PIC = { flower: 'daisy', bear: 'bear' };
// Each language: English word -> word with its article where the language uses one.
const HOME_LANGS = {
  spanish: { name: 'Spanish', words: { cat: 'el gato', dog: 'el perro', lion: 'el león', monkey: 'el mono', pig: 'el cerdo', zebra: 'la cebra', fish: 'el pez', turtle: 'la tortuga', bear: 'el oso', chick: 'el pollito', octopus: 'el pulpo', ladybird: 'la mariquita',
    apple: 'la manzana', banana: 'el plátano', orange: 'la naranja', strawberry: 'la fresa', cake: 'el pastel', cookie: 'la galleta', egg: 'el huevo', blueberry: 'el arándano',
    sun: 'el sol', star: 'la estrella', rainbow: 'el arcoíris', heart: 'el corazón', hat: 'el sombrero', balloon: 'el globo', present: 'el regalo', flower: 'la flor' } },
  french: { name: 'French', words: { cat: 'le chat', dog: 'le chien', lion: 'le lion', monkey: 'le singe', pig: 'le cochon', zebra: 'le zèbre', fish: 'le poisson', turtle: 'la tortue', bear: "l'ours", chick: 'le poussin', octopus: 'la pieuvre', ladybird: 'la coccinelle',
    apple: 'la pomme', banana: 'la banane', orange: "l'orange", strawberry: 'la fraise', cake: 'le gâteau', cookie: 'le biscuit', egg: "l'œuf", blueberry: 'la myrtille',
    sun: 'le soleil', star: "l'étoile", rainbow: "l'arc-en-ciel", heart: 'le cœur', hat: 'le chapeau', balloon: 'le ballon', present: 'le cadeau', flower: 'la fleur' } },
  german: { name: 'German', words: { cat: 'die Katze', dog: 'der Hund', lion: 'der Löwe', monkey: 'der Affe', pig: 'das Schwein', zebra: 'das Zebra', fish: 'der Fisch', turtle: 'die Schildkröte', bear: 'der Bär', chick: 'das Küken', octopus: 'der Krake', ladybird: 'der Marienkäfer',
    apple: 'der Apfel', banana: 'die Banane', orange: 'die Orange', strawberry: 'die Erdbeere', cake: 'der Kuchen', cookie: 'der Keks', egg: 'das Ei', blueberry: 'die Heidelbeere',
    sun: 'die Sonne', star: 'der Stern', rainbow: 'der Regenbogen', heart: 'das Herz', hat: 'der Hut', balloon: 'der Luftballon', present: 'das Geschenk', flower: 'die Blume' } },
  italian: { name: 'Italian', words: { cat: 'il gatto', dog: 'il cane', lion: 'il leone', monkey: 'la scimmia', pig: 'il maiale', zebra: 'la zebra', fish: 'il pesce', turtle: 'la tartaruga', bear: "l'orso", chick: 'il pulcino', octopus: 'il polpo', ladybird: 'la coccinella',
    apple: 'la mela', banana: 'la banana', orange: "l'arancia", strawberry: 'la fragola', cake: 'la torta', cookie: 'il biscotto', egg: "l'uovo", blueberry: 'il mirtillo',
    sun: 'il sole', star: 'la stella', rainbow: "l'arcobaleno", heart: 'il cuore', hat: 'il cappello', balloon: 'il palloncino', present: 'il regalo', flower: 'il fiore' } },
  portuguese: { name: 'Portuguese (Brazil)', words: { cat: 'o gato', dog: 'o cachorro', lion: 'o leão', monkey: 'o macaco', pig: 'o porco', zebra: 'a zebra', fish: 'o peixe', turtle: 'a tartaruga', bear: 'o urso', chick: 'o pintinho', octopus: 'o polvo', ladybird: 'a joaninha',
    apple: 'a maçã', banana: 'a banana', orange: 'a laranja', strawberry: 'o morango', cake: 'o bolo', cookie: 'o biscoito', egg: 'o ovo', blueberry: 'o mirtilo',
    sun: 'o sol', star: 'a estrela', rainbow: 'o arco-íris', heart: 'o coração', hat: 'o chapéu', balloon: 'o balão', present: 'o presente', flower: 'a flor' } },
  swahili: { name: 'Swahili', words: { cat: 'paka', dog: 'mbwa', lion: 'simba', monkey: 'tumbili', pig: 'nguruwe', zebra: 'punda milia', fish: 'samaki', turtle: 'kobe', bear: 'dubu', chick: 'kifaranga', octopus: 'pweza',
    apple: 'tufaha', banana: 'ndizi', orange: 'chungwa', strawberry: 'stroberi', cake: 'keki', cookie: 'biskuti', egg: 'yai',
    sun: 'jua', star: 'nyota', rainbow: 'upinde wa mvua', heart: 'moyo', hat: 'kofia', balloon: 'puto', present: 'zawadi', flower: 'ua' } },
};
const ALL_PICS = ['album', 'ant', 'apple', 'balloon', 'banana', 'bear', 'blocks', 'bluebell', 'blueberry', 'bowl', 'cake', 'cat', 'chalkboard', 'chick', 'cookie', 'cupcake', 'daisy', 'dog', 'donut', 'egg', 'envelope', 'fish', 'gorilla', 'hat', 'heart', 'ladybird', 'letterbox', 'lion', 'lolly', 'medal', 'monkey', 'mushroom', 'nest', 'octopus', 'orange', 'pig', 'popper', 'present', 'rainbow', 'rose', 'star', 'strawberry', 'sun', 'sunflower', 'tulip', 'turtle', 'zebra'];
const picFor = (w) => { const k = HOME_PIC[w] || w; return ALL_PICS.includes(k) ? ART(k) : ''; };

function makeHomeLang(o, paper) {
  const own = o.language === 'own';
  let pairs = [], langName;
  if (own) {
    langName = String(o.langname || '').trim().slice(0, 24) || 'Our language';
    pairs = listOf(o.custom, 24).map((l) => l.split(/\s*[=:]\s*/)).filter((p) => p.length >= 2 && p[0] && p[1]).map(([en, tr]) => [en.toLowerCase().slice(0, 20), tr.slice(0, 28)]);
    if (!pairs.length) pairs = HOME_WORDS.animals.slice(0, 8).map((w) => [w, '']);
  } else {
    const L = HOME_LANGS[o.language] || HOME_LANGS.spanish;
    langName = L.name;
    pairs = (HOME_WORDS[o.set] || HOME_WORDS.animals).filter((w) => L.words[w]).map((w) => [w, L.words[w]]);
  }
  const pages = [];
  if (o.layout === 'mat') {
    const pg = new Page(paper, `My words in ${langName}`, { subtitle: 'Say each word in both languages. Copy the word on the line.' });
    const rows = Math.min(pairs.length, 10), rh = (pg.room - 2) / rows;
    pairs.slice(0, rows).forEach(([en, tr], i) => {
      const y = pg.y + i * rh, c = i % PALETTE.length, src = picFor(en);
      pg.add(panel(pg.left, y + 1, pg.width, rh - 2, TINTS[c], '#e2ddf2', 6));
      if (src) pg.add(pic(src, pg.left + rh / 2 + 2, y + rh / 2, rh * 0.78));
      pg.add(txt(pg.left + rh + 8, y + rh * 0.42, tr || '________', fitFont(tr || '________', 7, 62, 0.52), { anchor: 'start', colour: PALETTE[c] }));
      pg.add(txt(pg.left + rh + 8, y + rh * 0.42 + 6, en, 4.2, { anchor: 'start', font: FONT, colour: SOFT }));
      pg.add(`<line x1="${pg.left + rh + 80}" x2="${pg.right - 6}" y1="${y + rh * 0.62}" y2="${y + rh * 0.62}" stroke="#b9b3d6" stroke-width="0.45"/>`);
    });
    pages.push(pg.svg());
    return pages;
  }
  // Flashcards: eight on a page, cut along the dashed lines.
  for (let p0 = 0; p0 < pairs.length; p0 += 8) {
    const pg = new Page(paper, '', { bare: true });
    const cw = pg.width / 2, ch = (pg.bottom - pg.m) / 4;
    pairs.slice(p0, p0 + 8).forEach(([en, tr], k) => {
      const i = p0 + k, x = pg.left + (k % 2) * cw, y = pg.m + Math.floor(k / 2) * ch, c = i % PALETTE.length, src = picFor(en);
      pg.add(`<rect x="${x + 1.5}" y="${y + 1.5}" width="${cw - 3}" height="${ch - 3}" rx="6" fill="${TINTS[c]}" stroke="#b9b3d6" stroke-width="0.4" stroke-dasharray="2 1.5"/>`);
      const size = ch * 0.5;
      if (src) pg.add(pic(src, x + cw / 2, y + 6 + size / 2, size));
      else pg.add(txt(x + cw / 2, y + 6 + size / 2 + 6, en, fitFont(en, 16, cw - 20), { colour: PALETTE[c] }));
      const big = tr || '';
      if (big) pg.add(txt(x + cw / 2, y + ch - 16, big, fitFont(big, 10, cw - 12, 0.55), { colour: PALETTE[c] }));
      else pg.add(`<line x1="${x + 14}" x2="${x + cw - 14}" y1="${y + ch - 16}" y2="${y + ch - 16}" stroke="#9a93b8" stroke-width="0.45"/>`);
      pg.add(txt(x + cw / 2, y + ch - 7, en, 4.6, { font: FONT, colour: SOFT }));
    });
    pg.add(txt(pg.w / 2, pg.bottom + 2, `${langName} and English flashcards. Cut along the dashed lines.`, 3.2, { font: FONT, colour: '#b8b3cc' }));
    pg.footer = () => {};
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ countdown chain (shared)
function chainPage(paper, title, sub, n, endArt, bottomLine) {
  const pg = new Page(paper, title, { subtitle: sub });
  const cols = n <= 10 ? 5 : n <= 21 ? 6 : 7, rows = Math.ceil((n + 1) / cols);
  const cell = Math.min(pg.width / cols, (pg.room - 30) / rows), gx = pg.left + (pg.width - cell * cols) / 2;
  const pos = (i) => { const r = Math.floor(i / cols), c = r % 2 ? cols - 1 - (i % cols) : i % cols; return [gx + c * cell + cell / 2, pg.y + r * cell + cell / 2]; };
  for (let i = 0; i < n; i++) { const [a, b] = pos(i), [c2, d] = pos(i + 1); pg.add(`<line x1="${a}" y1="${b}" x2="${c2}" y2="${d}" stroke="#e2ddf2" stroke-width="2.4" stroke-linecap="round"/>`); }
  for (let i = 0; i < n; i++) { const [x, y] = pos(i); pg.add(`<circle cx="${x}" cy="${y}" r="${cell * 0.36}" fill="#fff" stroke="${PALETTE[i % PALETTE.length]}" stroke-width="1"/>` + txt(x, y + cell * 0.12, n - i, cell * 0.32, { colour: PALETTE[i % PALETTE.length] })); }
  const [hx, hy] = pos(n);
  pg.add(pic(ART(endArt), hx, hy, cell * 0.9));
  const by = pg.y + rows * cell + 6;
  if (bottomLine) pg.add(txt(pg.w / 2, by + 6, bottomLine, 5, { font: FONT }) + `<line x1="${pg.left + 20}" x2="${pg.right - 20}" y1="${by + 18}" y2="${by + 18}" stroke="#b9b3d6" stroke-width="0.4"/>`);
  return pg.svg();
}

function checklistPage(paper, title, sub, items, name) {
  const pg = new Page(paper, title, { subtitle: sub, noName: !!name });
  const rh = (pg.room - 2) / items.length;
  items.forEach(([e, t], k) => {
    const y = pg.y + k * rh, c = PALETTE[k % PALETTE.length];
    pg.add(panel(pg.left, y + 1, pg.width, rh - 2, TINTS[k % TINTS.length], c, 6));
    pg.add(emoji(e, pg.left + rh / 2 + 3, y + rh / 2, Math.min(12, rh * 0.55)));
    pg.add(txt(pg.left + rh + 8, y + rh / 2 + 2, t, fitFont(t, 5.6, pg.width - rh - 30, 0.5), { anchor: 'start', font: FONT, colour: INK }));
    pg.add(`<path d="${starPath(pg.right - 11, y + rh / 2, Math.min(7.5, rh * 0.32), 0.46)}" fill="#fff" stroke="${c}" stroke-width="0.9" stroke-linejoin="round"/>`);
  });
  return pg.svg();
}

// ================================================================ ready for school pack
const SCHOOL_WORDS = { school: 'school', nursery: 'nursery', preschool: 'preschool', kindergarten: 'kindergarten', reception: 'Reception' };

function makeSchoolReady(o, paper) {
  const name = nameOf(o.name, '');
  const where = SCHOOL_WORDS[o.place] || 'school';
  const who = name || 'I';
  const pages = [];
  pages.push(packCover(paper, name ? `${name} is ready for ${where}!` : `Ready for ${where}!`, 'A little pack for a big step', 'owl', ['Do a page or two each day in the weeks before the big day.', 'Made at printpals.web.app'], '#e8f8f4'));
  pages.push(checklistPage(paper, 'I can do it myself!', `Practise each one at home. Colour a star when ${name || 'you'} can do it.`, [
    ['🥪', 'Open my lunchbox and my drink'], ['👟', 'Put on my shoes'], ['🧥', 'Hang up my coat and zip it up'], ['🚽', 'Go to the toilet and wash my hands'],
    ['🙋', 'Put my hand up and ask for help'], ['📛', 'Say my name and my teacher\'s name'], ['🧸', 'Tidy up my things'], ['🤝', 'Share and take turns'],
    ['✏️', 'Hold a pencil and write my name'], ['🎒', 'Carry my own bag'],
  ], name));
  // All about me, for the teacher
  const pg = new Page(paper, name ? `All about ${name}` : 'All about me', { subtitle: `Fill this in together and give it to the ${where === 'Reception' ? 'teacher' : 'teacher'} on the first day.`, noName: true });
  pg.add(`<rect x="${pg.left}" y="${pg.y}" width="62" height="72" rx="6" fill="#fff" stroke="${INK}" stroke-width="0.6" stroke-dasharray="3 2"/>` + txt(pg.left + 31, pg.y + 38, 'Photo or drawing', 4, { font: FONT, colour: SOFT }));
  let y = pg.y + 6;
  const line = (label, x, w) => { pg.add(txt(x, y, label, 4.4, { anchor: 'start', font: FONT, colour: SOFT }) + `<line x1="${x}" x2="${x + w}" y1="${y + 8}" y2="${y + 8}" stroke="#b9b3d6" stroke-width="0.45"/>`); y += 16; };
  ['My name is', 'I like to be called', 'I live with', 'My favourite toy is'].forEach((l) => line(l, pg.left + 70, pg.width - 70));
  y = pg.y + 82;
  ['My favourite food is', 'I am really good at', 'I feel happy when', 'I might need a little help with', 'When I feel sad or worried, it helps if you', 'Something special about me'].forEach((l) => line(l, pg.left, pg.width));
  pg.add(txt(pg.left, y + 2, 'A message from my grown-ups', 4.4, { anchor: 'start', font: FONT, colour: SOFT }));
  pg.add(`<rect x="${pg.left}" y="${y + 5}" width="${pg.width}" height="${Math.max(20, pg.bottom - y - 8)}" rx="6" fill="#fff" stroke="#b9b3d6" stroke-width="0.5"/>`);
  pages.push(pg.svg());
  // School morning routine
  const rt = packRun('routine', { routine: 'custom', layout: 'cards', name, steps: ['⏰ Wake up', '👕 Get dressed', '🥣 Eat breakfast', '🪥 Brush my teeth', '🎒 Get my bag', '👟 Shoes and coat on', '🤗 Big hug goodbye'].join('\n') }, paper, +o.seed || 1);
  if (rt.sheets.length) pages.push(rt.sheets[0]);
  pages.push(checklistPage(paper, 'My bag checklist', 'Pack your bag together the night before. Tick each one as it goes in!', [
    ['💧', 'Water bottle'], ['🥪', 'Lunch or snack'], ['📚', 'Book bag and reading book'], ['🧥', 'Coat or jumper'], ['👕', 'Spare clothes'], ['🧢', 'Sun hat or warm hat'], ['📝', 'Any letters for the teacher'],
  ], name));
  // Feelings about starting
  const fp = new Page(paper, `How I feel about ${where}`, { subtitle: 'Colour the faces that show how you feel. It is fine to feel more than one thing!' });
  const moods = ['happy', 'proud', 'worried', 'scared', 'silly', 'calm'], cw = fp.width / 3;
  moods.forEach((m, i) => { const cx = fp.left + cw * (i % 3 + 0.5), cy = fp.y + 22 + Math.floor(i / 3) * 44; fp.add(face(cx, cy, 15, m, false) + txt(cx, cy + 23, m, 5, { font: FONT })); });
  let fy = fp.y + 110;
  [`I am excited about`, `I am a little bit worried about`, `A grown-up can help me by`].forEach((l, k) => {
    fp.add(panel(fp.left, fy, fp.width, 34, TINTS[k * 2], PALETTE[k * 2], 6) + txt(fp.left + 6, fy + 9, l, 5.2, { anchor: 'start', colour: PALETTE[k * 2] }));
    for (let q = 1; q <= 2; q++) fp.add(`<line x1="${fp.left + 6}" x2="${fp.right - 6}" y1="${fy + 10 + q * 10}" y2="${fy + 10 + q * 10}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    fy += 40;
  });
  pages.push(fp.svg());
  pages.push(chainPage(paper, `Days until ${where} starts!`, 'Colour one circle every night before bed. When you reach the star, it is your big day!', Math.max(5, Math.min(30, +o.days || 14)), 'star', `On my first day, I am most looking forward to`));
  const tr = packRun('names', { names: name || 'My name', case: 'title', size: 'large' }, paper, +o.seed || 1);
  if (name && tr.sheets.length) pages.push(tr.sheets[0]);
  pages.push(...makeSigns({ kind: 'firstday', name, grade: SCHOOL_WORDS[o.place] ? where : '', seed: o.seed }, paper));
  return pages;
}

// ================================================================ holiday learning plan (Plus)
const BUCKET = ['Have a picnic', 'Build a den', 'Go on a nature walk', 'Make a paper boat', 'Bake something yummy', 'Visit the library', 'Have a teddy bears party', 'Paint a big picture',
  'Play a board game', 'Look at the stars', 'Make a card for someone', 'Plant a seed', 'Have a pyjama day', 'Do a puzzle', 'Put on a puppet show', 'Make a fort from cushions',
  'Go on a bike or scooter ride', 'Have a water play day', 'Learn a new song', 'Make a scrapbook of the holiday', 'Play hide and seek', 'Do a treasure hunt', 'Make a paper crown', 'Watch the sunset'];

function makeHolidayPlan(o, paper) {
  const theme = PACK_THEMES[o.theme] || PACK_THEMES.animals;
  const child = packChildren(o)[0];
  const g = ageGroup(child.age);
  const weeks = [2, 4, 6].includes(+o.weeks) ? +o.weeks : 4;
  const opt = { ...o, days: 3, per: +o.per || 1 };
  const who = child.name ? possessive(child.name) : 'My';
  const pages = [packCover(paper, `${who} holiday learning plan`, `${theme.label}, ${ageLabel(g)}`, theme.line[1 % theme.line.length], [`${weeks} weeks of little learning moments, 3 days a week.`, 'Made at printpals.web.app'], '#fff6e0')];
  // Bucket list
  const bl = new Page(paper, 'Our holiday bucket list', { subtitle: 'Tick off the fun things you do together. Add your own ideas at the bottom!', noName: true });
  const items = shuffle(BUCKET, rng(+o.seed || 1)).slice(0, 18), cw = bl.width / 2, rh = (bl.room - 30) / 9;
  items.forEach((t, i) => { const x = bl.left + (i % 2) * cw, y = bl.y + Math.floor(i / 2) * rh; bl.add(`<rect x="${x + 2}" y="${y + rh / 2 - 3.5}" width="7" height="7" rx="1.5" fill="#fff" stroke="${PALETTE[i % PALETTE.length]}" stroke-width="0.8"/>` + txt(x + 13, y + rh / 2 + 2, t, fitFont(t, 5, cw - 18, 0.5), { anchor: 'start', font: FONT })); });
  for (let l = 0; l < 2; l++) bl.add(`<rect x="${bl.left + 2}" y="${bl.bottom - 22 + l * 11}" width="7" height="7" rx="1.5" fill="#fff" stroke="${SOFT}" stroke-width="0.8"/><line x1="${bl.left + 13}" x2="${bl.right - 4}" y1="${bl.bottom - 15 + l * 11}" y2="${bl.bottom - 15 + l * 11}" stroke="#b9b3d6" stroke-width="0.4"/>`);
  pages.push(bl.svg());
  const all = [];
  for (let w = 1; w <= weeks; w++) {
    const lv = w > weeks / 2 ? { words: Math.min(6, g + (w === weeks ? 1 : 0)), numbers: g, fun: g } : { words: g, numbers: g, fun: g };
    all.push(packWeek(child, 0, theme, opt, paper, w, lv));
  }
  const labels = weeks === 2 ? ['Warm up', 'Keep it fresh'] : weeks === 4 ? ['Warm up', 'Keep going', 'Keep it fresh', 'Ready for school'] : ['Warm up', 'Keep going', 'Halfway hooray', 'Keep it fresh', 'Almost there', 'Ready for school'];
  pages.push(monthOverview(paper, child.name, theme, g, all, labels).replace(/learning month/g, 'holiday plan').replace('Four weeks that get a little harder each week.', `${weeks} weeks, 3 days a week.`).replace('When I finish my month, we will celebrate by', 'When I finish my holiday plan, we will celebrate by'));
  all.forEach((w) => pages.push(...w.sheets));
  const log = packRun('readinglog', { name: child.name, log: true, shelf: false, challenge: false }, paper, +o.seed || 1);
  if (log.sheets.length) pages.push(log.sheets[0]);
  if (o.certificate !== false) pages.push(packCertificate(paper, child.name, 'You finished your holiday learning plan! What a brilliant holiday.'));
  if (o.key !== false) all.forEach((w) => pages.push(...w.keys));
  return pages;
}

// ================================================================ milestone signs
const SIGNS = {
  firstday: { top: 'My first day of', fill: (g) => g || 'school', rows: ['I am _ years old', 'My teacher is', 'My favourite colour is', 'My favourite food is', 'When I grow up I want to be'], art: 'star' },
  lastday: { top: 'My last day of', fill: (g) => g || 'school', rows: ['This year I learned', 'My favourite memory is', 'My best friend is', 'Next year I will be in', 'When I grow up I want to be'], art: 'medal' },
  hundred: { top: 'I am 100 days', fill: () => 'smarter!', rows: ['I can now', 'My favourite thing to learn is', 'My teacher is', 'I am _ years old'], art: 'star' },
  birthday: { top: 'Today I am', fill: (g, age) => (age ? `${age} years old!` : 'one year older!'), rows: ['My favourite toy is', 'My favourite food is', 'My best friend is', 'This year I want to learn'], art: 'cake' },
  tooth: { top: 'I lost my', fill: () => 'first tooth!', rows: ['I am _ years old', 'It fell out when I was', 'The tooth fairy brought me'], art: 'star' },
  sibling: { top: 'I am a big', fill: (g) => g || 'sibling!', rows: ['My baby is called', 'I can help by', 'I love my baby because'], art: 'heart' },
};

function makeSigns(o, paper) {
  const sg = SIGNS[o.kind] || SIGNS.firstday;
  const name = nameOf(o.name, '');
  const grade = String(o.grade || '').trim().slice(0, 24);
  const age = String(o.age || '').trim().slice(0, 3);
  const vals = { 'My teacher is': o.teacher, 'My favourite colour is': o.colour, 'My favourite food is': o.food, 'When I grow up I want to be': o.grow };
  const pg = new Page(paper, '', { bare: true, tint: '#fffdf8' });
  const cx = pg.w / 2;
  pg.add(`<rect x="${pg.left - 3}" y="${pg.m - 3}" width="${pg.width + 6}" height="${pg.bottom - pg.m + 3}" rx="12" fill="#fff" stroke="#ff7eb6" stroke-width="1.6"/>`);
  for (let i = 0; i < 18; i++) { const x = pg.left + 6 + (i % 9) * ((pg.width - 12) / 8), y = i < 9 ? pg.m + 5 : pg.bottom - 8; pg.add(`<path d="${starPath(x, y, 2.6, 0.45)}" fill="${PALETTE[i % PALETTE.length]}"/>`); }
  let y = pg.m + 30;
  pg.add(txt(cx, y, sg.top, 12, { colour: '#8a3fd1' }));
  y += 26;
  bubbleText(pg, sg.fill(grade, age), cx, y, pg.width - 30, 24);
  y += 18;
  pg.add(pic(ART(sg.art), cx, y + 26, 52));
  y += 62;
  if (name) { bubbleText(pg, name, cx, y + 14, pg.width - 40, 20); y += 22; }
  const dateTxt = String(o.date || '').trim() || new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
  pg.add(txt(cx, y + 6, dateTxt, 6, { colour: SOFT, font: FONT }));
  y += 14;
  const rh = Math.min(20, (pg.bottom - 14 - y) / sg.rows.length);
  sg.rows.forEach((r, i) => {
    const val = String(vals[r] || '').trim().slice(0, 30);
    const label = r.replace('_', age || '___');
    pg.add(panel(pg.left + 10, y + i * rh + 1, pg.width - 20, rh - 3, TINTS[i % TINTS.length], PALETTE[i % PALETTE.length], 6));
    pg.add(txt(pg.left + 16, y + i * rh + rh / 2 + 1.5, label, 5, { anchor: 'start', font: FONT, colour: INK }));
    if (val) pg.add(txt(pg.right - 16, y + i * rh + rh / 2 + 1.5, val, fitFont(val, 6.4, pg.width * 0.4), { anchor: 'end', colour: PALETTE[i % PALETTE.length] }));
  });
  pg.footer = () => {};
  return [pg.svg()];
}

// ================================================================ story dice
const DICE_SETS = {
  adventure: [
    ['Who?', ['lion', 'monkey', 'pig', 'cat', 'dog', 'octopus']],
    ['Where?', ['🏰', '🌳', '🏖️', '🚀', '🏠', '🌋']],
    ['What?', ['present', 'balloon', 'hat', 'cake', 'star', 'egg']],
  ],
  feelings: [
    ['Who?', ['zebra', 'turtle', 'bear', 'chick', 'gorilla', 'ladybird']],
    ['Feels?', ['😀', '😢', '😠', '😨', '😲', '🥱']],
    ['Because?', ['present', 'rainbow', 'popper', 'cookie', 'heart', 'mushroom']],
  ],
};

function dieNet(pg, x, y, s, faces, colour, label) {
  const layout = [[1, 0], [0, 1], [1, 1], [2, 1], [3, 1], [1, 2]];
  layout.forEach(([c, r], i) => {
    const fx = x + c * s, fy = y + r * s, f = faces[i];
    pg.add(`<rect x="${fx}" y="${fy}" width="${s}" height="${s}" fill="#fff" stroke="${INK}" stroke-width="0.6"/>`);
    pg.add(ALL_PICS.includes(f) ? pic(ART(f), fx + s / 2, fy + s / 2, s * 0.78) : emoji(f, fx + s / 2, fy + s / 2, s * 0.6));
  });
  const tab = (tx, ty, w, h) => pg.add(`<rect x="${tx}" y="${ty}" width="${w}" height="${h}" fill="#f4f1fb" stroke="${INK}" stroke-width="0.4" stroke-dasharray="1.8 1.2"/>`);
  tab(x + s, y - 7, s, 7); tab(x - 7, y + s, 7, s); tab(x + 4 * s, y + s, 7, s); tab(x + s, y + 3 * s, s, 7); tab(x, y + s - 7, s, 7); tab(x + 2 * s, y + s - 7, s, 7);
  pg.add(txt(x + 3 * s, y + s * 0.55, label, 7, { colour }));
}

function makeStoryDice(o, paper) {
  const set = DICE_SETS[o.set] || DICE_SETS.adventure;
  const pages = [];
  for (let d = 0; d < 3; d += 2) {
    const pg = new Page(paper, d ? 'Story dice (page 2)' : 'Story dice', { subtitle: 'Cut out each dice, fold on the lines and glue the grey tabs inside. Roll all three and tell a story!', noName: true });
    const s = Math.min(34, (pg.room - 46) / 6);
    set.slice(d, d + 2).forEach(([label, faces], k) => dieNet(pg, pg.left + 12, pg.y + 12 + k * (s * 3 + 24), s, faces, PALETTE[(d + k) * 2 % PALETTE.length], label));
    pages.push(pg.svg());
  }
  if (o.mat !== false) {
    const pg = new Page(paper, 'My story', { subtitle: 'Roll the dice. Draw and write what happens at the start, in the middle and at the end.' });
    const bh = (pg.room - 6) / 3;
    ['Once upon a time...', 'Then...', 'In the end...'].forEach((t, i) => {
      const y = pg.y + i * bh;
      pg.add(panel(pg.left, y + 1, pg.width, bh - 4, TINTS[i * 2], PALETTE[i * 2], 7) + txt(pg.left + 6, y + 10, t, 6, { anchor: 'start', colour: PALETTE[i * 2] }));
      pg.add(`<rect x="${pg.left + 6}" y="${y + 14}" width="${pg.width * 0.42}" height="${bh - 22}" rx="4" fill="#fff" stroke="#d9d4ec" stroke-width="0.5"/>`);
      for (let l = 1; l <= 4; l++) pg.add(`<line x1="${pg.left + pg.width * 0.42 + 12}" x2="${pg.right - 6}" y1="${y + 14 + l * (bh - 22) / 4.2}" y2="${y + 14 + l * (bh - 22) / 4.2}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    });
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ sibling peace pack
const KIND_COUPONS = ['I will help you tidy up', 'You choose the game today', 'One big hug, any time', 'You can go first', 'I will share my snack', 'I will read you a story', 'You pick the film', 'I will play what you want for 10 minutes'];

function makeSiblings(o, paper) {
  const kids = listOf(o.names, 4).map((n) => nameOf(n, '')).filter(Boolean);
  const names = kids.length >= 2 ? kids : ['Mia', 'Leo'];
  const want = (k) => o[k] !== false;
  const pages = [];
  if (want('turns')) {
    const pg = new Page(paper, 'Whose turn is it?', { subtitle: 'No more arguing! Take turns each day. Write or colour the name of whose turn it is.', noName: true });
    const jobs = listOf(o.jobs, 6).length ? listOf(o.jobs, 6) : ['Goes first', 'Chooses the film', 'Sits in the front', 'Picks the story', 'Presses the lift button'];
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const lw = 50, cw = (pg.width - lw) / 7, rh = Math.min(36, (pg.room - 20) / jobs.length);
    days.forEach((d, i) => pg.add(txt(pg.left + lw + cw * (i + 0.5), pg.y + 6, d, 4.4, { colour: PALETTE[i] })));
    jobs.forEach((j, r) => {
      const y = pg.y + 10 + r * rh;
      pg.add(panel(pg.left, y, pg.width, rh - 2, TINTS[r % TINTS.length], '#e2ddf2', 5) + txt(pg.left + 4, y + rh / 2 + 1, j, fitFont(j, 4.6, lw - 6, 0.5), { anchor: 'start', font: FONT }));
      days.forEach((d, i) => {
        const n = names[(i + r) % names.length];
        pg.add(`<rect x="${pg.left + lw + cw * i + 1}" y="${y + 2}" width="${cw - 2}" height="${rh - 6}" rx="3" fill="#fff"/>` + txt(pg.left + lw + cw * (i + 0.5), y + rh / 2 + 1, n, fitFont(n, 4.2, cw - 4, 0.52), { colour: PALETTE[names.indexOf(n) % PALETTE.length] }));
      });
    });
    pages.push(pg.svg());
  }
  if (want('spinner')) {
    const pg = new Page(paper, 'Turn spinner', { subtitle: 'Put a pencil through a paperclip on the middle dot and flick the paperclip. Where it stops, that person goes first!', noName: true });
    const cx = pg.w / 2, cy = pg.y + 80, R = 72, n = names.length;
    names.forEach((nm, i) => {
      const a0 = (i / n) * Math.PI * 2 - Math.PI / 2, a1 = ((i + 1) / n) * Math.PI * 2 - Math.PI / 2, mid = (a0 + a1) / 2;
      const d = `M${cx} ${cy} L${cx + Math.cos(a0) * R} ${cy + Math.sin(a0) * R} A${R} ${R} 0 ${n <= 1 ? 1 : 0} 1 ${cx + Math.cos(a1) * R} ${cy + Math.sin(a1) * R} Z`;
      pg.add(`<path d="${d}" fill="${TINTS[i % TINTS.length]}" stroke="${INK}" stroke-width="0.8"/>`);
      pg.add(txt(cx + Math.cos(mid) * R * 0.6, cy + Math.sin(mid) * R * 0.6 + 3, nm, fitFont(nm, 10, R * 0.8), { colour: PALETTE[i % PALETTE.length] }));
    });
    pg.add(`<circle cx="${cx}" cy="${cy}" r="3" fill="${INK}"/>`);
    const ry = cy + R + 16;
    pg.add(txt(cx, ry, 'Good sports cheer for each other!', 7, { colour: '#8a3fd1' }));
    pg.add(pic(ART('star'), cx - 70, ry - 2, 14) + pic(ART('star'), cx + 70, ry - 2, 14));
    pages.push(pg.svg());
  }
  if (want('rules')) {
    const pg = new Page(paper, 'We are a team!', { subtitle: 'Read the team rules together, then everyone signs their name.', noName: true });
    const rules = ['We use kind words, even when we are cross', 'We take turns and share', 'We ask before we borrow', 'We stop when someone says stop', 'We say sorry and try again', 'We cheer each other on'];
    const rh = (pg.room - 60) / rules.length;
    rules.forEach((r, i) => { const y = pg.y + i * rh; pg.add(panel(pg.left, y + 1, pg.width, rh - 3, TINTS[i], PALETTE[i], 6) + pic(ART('heart'), pg.left + 9, y + rh / 2, 9) + txt(pg.left + 18, y + rh / 2 + 2, r, fitFont(r, 5.8, pg.width - 24, 0.5), { anchor: 'start', font: FONT })); });
    const sy = pg.bottom - 42, sw = pg.width / names.length;
    names.forEach((nm, i) => pg.add(txt(pg.left + sw * (i + 0.5), sy + 10, nm, 6, { colour: PALETTE[i % PALETTE.length] }) + `<line x1="${pg.left + sw * i + 8}" x2="${pg.left + sw * (i + 1) - 8}" y1="${sy + 30}" y2="${sy + 30}" stroke="#b9b3d6" stroke-width="0.45"/>` + txt(pg.left + sw * (i + 0.5), sy + 36, 'signed', 3.6, { font: FONT, colour: SOFT })));
    pages.push(pg.svg());
  }
  if (want('coupons')) {
    const pg = new Page(paper, 'Kindness coupons', { subtitle: 'Cut them out and give one to your brother or sister. They can use it whenever they like!', noName: true });
    const cw = pg.width / 2, ch = (pg.room - 2) / 4;
    KIND_COUPONS.forEach((t, i) => {
      const x = pg.left + (i % 2) * cw, y = pg.y + Math.floor(i / 2) * ch;
      pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="8" fill="${TINTS[i % TINTS.length]}" stroke="${PALETTE[i % PALETTE.length]}" stroke-width="0.9" stroke-dasharray="3 1.8"/>`);
      pg.add(txt(x + cw / 2, y + 12, 'Kindness coupon', 4.4, { colour: PALETTE[i % PALETTE.length] }));
      textLines(pg, wrap(t, 22), x + cw / 2, y + ch / 2, 6, { anchor: 'middle', weight: 800, font: TITLE_FONT });
      pg.add(txt(x + 8, y + ch - 8, 'From', 3.8, { anchor: 'start', font: FONT, colour: SOFT }) + `<line x1="${x + 18}" x2="${x + cw - 10}" y1="${y + ch - 8}" y2="${y + ch - 8}" stroke="#b9b3d6" stroke-width="0.4"/>`);
    });
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ screen time tickets
const EARN_IDEAS = ['Read a book: 1 ticket', 'Play outside for 30 minutes: 1 ticket', 'Help with a job at home: 1 ticket', 'Finish homework: 1 ticket', 'Tidy my room: 1 ticket', 'Do something kind: 1 ticket', 'Practise an instrument: 1 ticket'];

function makeScreenTime(o, paper) {
  const name = nameOf(o.name, '');
  const mins = [15, 30].includes(+o.minutes) ? +o.minutes : 15;
  const pages = [];
  const pg = new Page(paper, name ? `${possessive(name)} screen time tickets` : 'Screen time tickets', { subtitle: `Earn a ticket, then swap it for ${mins} minutes of screen time. Cut them out and keep them in a jar!`, noName: true });
  const cw = pg.width / 3, ch = (pg.room - 2) / 5;
  for (let i = 0; i < 15; i++) {
    const x = pg.left + (i % 3) * cw, y = pg.y + Math.floor(i / 3) * ch, c = PALETTE[i % PALETTE.length];
    const d = `M${x + 3} ${y + 3} H${x + cw - 3} V${y + ch / 2 - 4} A4 4 0 0 0 ${x + cw - 3} ${y + ch / 2 + 4} V${y + ch - 3} H${x + 3} V${y + ch / 2 + 4} A4 4 0 0 0 ${x + 3} ${y + ch / 2 - 4} Z`;
    pg.add(`<path d="${d}" fill="${TINTS[i % TINTS.length]}" stroke="${c}" stroke-width="0.9" stroke-dasharray="2.5 1.5"/>`);
    pg.add(emoji('📺', x + 14, y + ch / 2, 11));
    pg.add(txt(x + cw / 2 + 7, y + ch / 2 - 1, `${mins} minutes`, 6.2, { colour: c }));
    pg.add(txt(x + cw / 2 + 7, y + ch / 2 + 6, name || 'screen time', fitFont(name || 'screen time', 4.4, cw - 30), { font: FONT, colour: SOFT }));
  }
  pages.push(pg.svg());
  if (o.chart !== false) {
    const p2 = new Page(paper, 'How to earn a ticket', { subtitle: 'Agree these together, then stick this chart on the fridge.', noName: true });
    const earn = listOf(o.earn, 10).length ? listOf(o.earn, 10) : EARN_IDEAS;
    const rh = Math.min(22, (p2.room - 70) / earn.length);
    earn.forEach((t, i) => { const y = p2.y + i * rh; p2.add(panel(p2.left, y + 1, p2.width, rh - 3, TINTS[i % TINTS.length], PALETTE[i % PALETTE.length], 6) + pic(ART('star'), p2.left + 9, y + rh / 2, 9) + txt(p2.left + 18, y + rh / 2 + 2, t, fitFont(t, 5.6, p2.width - 24, 0.5), { anchor: 'start', font: FONT })); });
    const ry = p2.y + earn.length * rh + 8;
    p2.add(panel(p2.left, ry, p2.width, 52, '#fff6e0', '#ffb938', 8) + txt(p2.left + 8, ry + 11, 'Our screen time rules', 6, { anchor: 'start', colour: '#e08a00' }));
    ['Tickets can be used after jobs and homework are done.', `One ticket = ${mins} minutes.`, 'No screens at meal times or an hour before bed.'].forEach((t, i) => p2.add(txt(p2.left + 8, ry + 22 + i * 9, `• ${t}`, 4.8, { anchor: 'start', font: FONT })));
    pages.push(p2.svg());
  }
  return pages;
}

// ================================================================ lunchbox notes
const LOVE_NOTES = ['I am so proud of you!', 'You make my heart smile.', 'Have the best day, {name}!', 'You are brave and kind.', 'I can\'t wait to hear about your day!', 'Try your best. That is all that matters.',
  'Big hugs are waiting for you at home!', 'You are loved more than all the stars.', 'Eat up and grow strong!', 'You can do hard things.', 'Thinking of you right now!', 'You are one of a kind.'];
const JOKES = [['Why did the banana go to the doctor?', 'It was not peeling well!'], ['What do you call a sleeping dinosaur?', 'A dino-snore!'], ['Why are fish so clever?', 'They live in schools!'],
  ['What do you call a bear with no teeth?', 'A gummy bear!'], ['Why can\'t a bicycle stand up by itself?', 'It is two tired!'], ['What did one plate say to the other?', 'Lunch is on me!'],
  ['Why did the cookie go to the doctor?', 'It felt crummy!'], ['What do you call a dog who does magic?', 'A labracadabrador!'], ['Why did the teddy bear say no to pudding?', 'It was already stuffed!'],
  ['What has hands but cannot clap?', 'A clock!'], ['What do you call a fish with no eyes?', 'A fsh!'], ['Why did the student eat their homework?', 'The teacher said it was a piece of cake!']];

function makeLunchNotes(o, paper) {
  const rand = rng(+o.seed || 1);
  const name = nameOf(o.name, '');
  const from = String(o.from || '').trim().slice(0, 20);
  const colourIn = o.style === 'colour';
  const kind = o.kind || 'mix';
  const love = shuffle(LOVE_NOTES, rand), jokes = shuffle(JOKES, rand);
  const pg = new Page(paper, '', { bare: true });
  const cw = pg.width / 2, ch = (pg.bottom - pg.m) / 5;
  for (let i = 0; i < 10; i++) {
    const x = pg.left + (i % 2) * cw, y = pg.m + Math.floor(i / 2) * ch, c = PALETTE[i % PALETTE.length];
    pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="8" fill="${colourIn ? '#fff' : TINTS[i % TINTS.length]}" stroke="${colourIn ? INK : c}" stroke-width="0.8" stroke-dasharray="3 1.8"/>`);
    const art = ['heart', 'star', 'sun', 'rainbow', 'present', 'cupcake', 'balloon', 'strawberry', 'ladybird', 'chick'][i];
    if (colourIn) pg.add(`<g transform="translate(${x + 6} ${y + ch / 2 - 11}) scale(0.11)">${colouringArt(['bee', 'owl', 'cat', 'fish', 'snail', 'butterfly', 'bunny', 'ladybird', 'turtle', 'frog'][i])}</g>`);
    else pg.add(pic(ART(art), x + 16, y + ch / 2, 20));
    const tx = x + 32, tw = cw - 40;
    const isJoke = kind === 'jokes' || (kind === 'mix' && i % 2 === 1);
    if (kind === 'blank') {
      pg.add(txt(tx, y + 12, name ? `Dear ${name},` : 'Dear', 5, { anchor: 'start', colour: colourIn ? INK : c }));
      for (let l = 1; l <= 3; l++) pg.add(`<line x1="${tx}" x2="${tx + tw}" y1="${y + 12 + l * 8}" y2="${y + 12 + l * 8}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    } else if (isJoke) {
      const [q, a] = jokes[Math.floor(i / 2) % jokes.length];
      const ql = wrap(q, 26);
      textLines(pg, ql, tx, y + 11, 4.4, { weight: 800 });
      pg.add(`<g transform="rotate(180 ${tx + tw / 2} ${y + ch - 10})">${txt(tx + tw / 2, y + ch - 10, a, fitFont(a, 4.4, tw, 0.5), { colour: colourIn ? INK : c })}</g>`);
      pg.add(txt(tx, y + ch - 17, 'Turn me upside down for the answer!', 3, { anchor: 'start', font: FONT, colour: SOFT }));
    } else {
      const note = love[i % love.length].replace('{name}', name || 'superstar');
      textLines(pg, wrap(note, 22), tx, y + 14, 5.4, { weight: 800, font: TITLE_FONT, colour: colourIn ? INK : c });
    }
    if (from && !isJoke) pg.add(txt(x + cw - 8, y + ch - 7, `Love, ${from}`, 4, { anchor: 'end', font: FONT, colour: SOFT }));
  }
  pg.footer = () => {};
  return [pg.svg()];
}

Object.assign(MAKERS, { homelang: makeHomeLang, schoolready: makeSchoolReady, holidayplan: makeHolidayPlan, signs: makeSigns, storydice: makeStoryDice, siblings: makeSiblings, screentime: makeScreenTime, lunchnotes: makeLunchNotes });

;
// PrintPals batch 13: big feelings toolkit, sleep pack, food explorer, social stories,
// personalised storybook (Plus), conversation cards, gratitude journal and potty training pack.

const cardGrid = (pg, n, cols) => { const rows = Math.ceil(n / cols); return { cw: pg.width / cols, ch: (pg.room - 2) / rows }; };

// ================================================================ big feelings toolkit
const CALM_CHOICES = [['🌬️', 'Take 5 slow breaths'], ['🤗', 'Ask for a hug'], ['🔢', 'Count to 10'], ['💧', 'Drink some water'], ['🖍️', 'Draw how I feel'], ['🎵', 'Listen to music'],
  ['🦘', 'Jump 10 times'], ['📚', 'Read a book'], ['🧸', 'Cuddle a teddy'], ['🛋️', 'Squeeze a cushion'], ['🏠', 'Go to my calm spot'], ['🗣️', 'Talk to a grown-up']];

function breathingPanel(pg, kind, x, y, w, h, c) {
  const cx = x + w / 2, cy = y + h * 0.46, r = Math.min(w, h) * 0.3;
  const st = `fill="none" stroke="${c}" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"`;
  const titles = { star: ['Star breathing', 'Trace up a point as you breathe in. Trace down as you breathe out.'], rainbow: ['Rainbow breathing', 'Breathe in as you trace up the rainbow. Breathe out as you trace down.'],
    balloon: ['Balloon breathing', 'Breathe in and make your tummy big like a balloon. Breathe out slowly: pssss.'], flower: ['Smell and blow', 'Smell the flower (breathe in). Blow out the candle (breathe out).'],
    bunny: ['Bunny breaths', 'Three quick sniffs through your nose, then one long breath out.'], hug: ['Butterfly hug', 'Cross your arms, tap your shoulders slowly, and count to 10.'] };
  const [t, d] = titles[kind];
  pg.add(panel(x + 2, y + 2, w - 4, h - 4, '#fff', c, 7) + txt(cx, y + 11, t, 6, { colour: c }));
  if (kind === 'star') { pg.add(`<path d="${starPath(cx, cy, r, 0.45)}" ${st}/>`); for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * 0.45 : r; pg.add(`<circle cx="${cx + Math.cos(a) * rr}" cy="${cy + Math.sin(a) * rr}" r="1.2" fill="${c}"/>`); } }
  else if (kind === 'rainbow') { [1, 0.78, 0.56].forEach((k, i) => pg.add(`<path d="M${cx - r * 1.3 * k} ${cy + r * 0.5} A${r * 1.3 * k} ${r * 1.3 * k} 0 0 1 ${cx + r * 1.3 * k} ${cy + r * 0.5}" fill="none" stroke="${PALETTE[i * 2]}" stroke-width="2.2" stroke-linecap="round"/>`)); pg.add(txt(cx - r * 1.3, cy + r * 0.5 + 6, 'in', 4, { font: FONT, colour: SOFT }) + txt(cx + r * 1.3, cy + r * 0.5 + 6, 'out', 4, { font: FONT, colour: SOFT })); }
  else if (kind === 'balloon') { pg.add(pic(ART('balloon'), cx - r * 0.7, cy + r * 0.2, r * 0.8) + pic(ART('balloon'), cx + r * 0.5, cy, r * 1.5) + txt(cx - r * 0.7, cy + r * 0.9, 'out', 4, { font: FONT, colour: SOFT }) + txt(cx + r * 0.5, cy + r * 1.05, 'in', 4, { font: FONT, colour: SOFT })); }
  else if (kind === 'flower') { pg.add(emoji('🌷', cx - r * 0.7, cy, r * 1.1) + emoji('🕯️', cx + r * 0.7, cy, r * 1.1)); }
  else if (kind === 'bunny') { pg.add(emoji('🐰', cx, cy, r * 1.5)); }
  else pg.add(emoji('🦋', cx, cy, r * 1.5));
  textLines(pg, wrap(d, Math.floor((w - 12) / 2.5)), cx, y + h - 17, 4.2, { anchor: 'middle', font: FONT, weight: 700, colour: INK });
}

function makeCalmKit(o, paper) {
  const want = (k) => o[k] !== false;
  const pages = [];
  if (want('breathing')) {
    const pg = new Page(paper, 'Calm breathing', { subtitle: 'When big feelings come, try a breathing game. Practise when you feel calm, so it is easy when you need it.' });
    const { cw, ch } = cardGrid(pg, 6, 2);
    ['star', 'rainbow', 'balloon', 'flower', 'bunny', 'hug'].forEach((k, i) => breathingPanel(pg, k, pg.left + (i % 2) * cw, pg.y + Math.floor(i / 2) * ch, cw, ch, PALETTE[i]));
    pages.push(pg.svg());
  }
  if (want('choices')) {
    const pg = new Page(paper, 'My calm down choices', { subtitle: 'Cut out the cards. When you feel upset, pick one to help your body feel calm again.' });
    const { cw, ch } = cardGrid(pg, 12, 3);
    CALM_CHOICES.forEach(([e, t], i) => {
      const x = pg.left + (i % 3) * cw, y = pg.y + Math.floor(i / 3) * ch;
      pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="7" fill="${TINTS[i % TINTS.length]}" stroke="#b9b3d6" stroke-width="0.4" stroke-dasharray="2 1.5"/>`);
      pg.add(emoji(e, x + cw / 2, y + ch * 0.4, ch * 0.34) + txt(x + cw / 2, y + ch - 10, t, fitFont(t, 5.2, cw - 8, 0.5), { colour: PALETTE[i % PALETTE.length] }));
    });
    pages.push(pg.svg());
  }
  if (want('thermometer')) {
    const pg = new Page(paper, 'My feelings thermometer', { subtitle: 'Point to how big your feeling is. Then try something that helps.' });
    const levels = [['5', 'About to explode', '#ff4d4d', 'Stop. Breathe. Find a grown-up.'], ['4', 'Very upset', '#ff8a4d', 'Go to my calm spot'], ['3', 'Worried or cross', '#ffc93c', 'Take 5 slow breaths'], ['2', 'A bit wobbly', '#9ad86b', 'Get a drink or a hug'], ['1', 'Calm and happy', '#3fbf60', 'Keep going!']];
    const tx = pg.left + 20, top = pg.y + 6, lh = (pg.room - 30) / 5;
    pg.add(`<rect x="${tx - 9}" y="${top}" width="18" height="${lh * 5}" rx="9" fill="#fff" stroke="${INK}" stroke-width="0.8"/><circle cx="${tx}" cy="${top + lh * 5 + 10}" r="13" fill="#3fbf60" stroke="${INK}" stroke-width="0.8"/>`);
    levels.forEach(([n, t, c, help], i) => {
      const y = top + i * lh;
      pg.add(`<rect x="${tx - 6}" y="${y + 3}" width="12" height="${lh - 4}" rx="4" fill="${c}"/>`);
      pg.add(panel(tx + 18, y + 2, pg.right - tx - 18, lh - 4, '#fff', c, 7));
      pg.add(face(tx + 32, y + lh / 2, Math.min(10, lh * 0.3), ['angry', 'sad', 'worried', 'calm', 'happy'][i], true));
      pg.add(txt(tx + 48, y + lh / 2 - 2, `${n}. ${t}`, 6.4, { anchor: 'start', colour: INK }) + txt(tx + 48, y + lh / 2 + 7, `What helps: ${help}`, 4.6, { anchor: 'start', font: FONT, colour: SOFT }));
    });
    pages.push(pg.svg());
  }
  if (want('worry')) {
    const pg = new Page(paper, 'My worry jar', { subtitle: 'Write or draw a worry on a slip, fold it and pop it in the jar. A grown-up will read it with you later.' });
    const jx = pg.left + 8, jy = pg.y + 4, jw = 76, jh = 110;
    pg.add(`<path d="M${jx + 14} ${jy + 10} H${jx + jw - 14} V${jy + 18} Q${jx + jw} ${jy + 26} ${jx + jw} ${jy + 44} V${jy + jh - 10} Q${jx + jw} ${jy + jh} ${jx + jw - 10} ${jy + jh} H${jx + 10} Q${jx} ${jy + jh} ${jx} ${jy + jh - 10} V${jy + 44} Q${jx} ${jy + 26} ${jx + 14} ${jy + 18} Z" fill="#eaf6ff" stroke="${INK}" stroke-width="0.9"/><rect x="${jx + 12}" y="${jy}" width="${jw - 24}" height="11" rx="2" fill="#ffd6e4" stroke="${INK}" stroke-width="0.8"/>`);
    pg.add(txt(jx + jw / 2, jy + 66, 'Worries', 8, { colour: '#6c8cff' }) + pic(ART('heart'), jx + jw / 2, jy + 84, 14));
    const bx = jx + jw + 12;
    textLines(pg, wrap('Everyone has worries sometimes. Sharing a worry makes it smaller. Once a day, open the jar together, read the worries, and talk about them. Throw away the ones that are gone!', 40), bx, jy + 12, 4.6, { font: FONT, weight: 700, colour: '#5d5680' });
    const sy = jy + jh + 12;
    scissors(pg, sy - 5);
    const sw = pg.width / 2, sh = (pg.bottom - sy) / 4;
    for (let i = 0; i < 8; i++) {
      const x = pg.left + (i % 2) * sw, y = sy + Math.floor(i / 2) * sh;
      pg.add(`<rect x="${x + 2}" y="${y + 1.5}" width="${sw - 4}" height="${sh - 3}" rx="5" fill="#fff" stroke="#b9b3d6" stroke-width="0.4" stroke-dasharray="2 1.5"/>` + txt(x + 7, y + 9, 'My worry is...', 4.4, { anchor: 'start', font: FONT, colour: PALETTE[i % PALETTE.length] }));
      pg.add(`<line x1="${x + 7}" x2="${x + sw - 8}" y1="${y + sh - 7}" y2="${y + sh - 7}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    }
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ sleep pack
function makeSleep(o, paper) {
  const name = nameOf(o.name, '');
  const want = (k) => o[k] !== false;
  const pages = [];
  if (want('ok')) {
    const pg = new Page(paper, '', { bare: true });
    const h = (pg.bottom - pg.m - 8) / 2;
    [['night', 'Still sleepy time', 'Stay in bed and rest. The sun is not up yet.', '#2d2350', '#ffd23f', '🌙'], ['day', 'Good morning!', 'The sun is up. You can get up now!', '#fff6e0', '#ff9f1c', '☀️']].forEach(([k, t, sub, bg, fg, e], i) => {
      const y = pg.m + i * (h + 8);
      pg.add(`<rect x="${pg.left}" y="${y}" width="${pg.width}" height="${h}" rx="14" fill="${bg}" stroke="${fg}" stroke-width="1.4"/>`);
      pg.add(emoji(e, pg.w / 2, y + h * 0.36, h * 0.36));
      pg.add(txt(pg.w / 2, y + h * 0.72, t, 13, { colour: fg }));
      pg.add(txt(pg.w / 2, y + h * 0.72 + 10, sub, 5.2, { font: FONT, colour: k === 'night' ? '#d8d3ee' : INK }));
      pg.add(txt(pg.w / 2, y + h - 8, k === 'night' ? `Wake up time: ______` : (name ? `Well done for staying in bed, ${name}!` : 'Well done for staying in bed!'), 4.6, { font: FONT, colour: k === 'night' ? '#d8d3ee' : SOFT }));
    });
    pg.add(txt(pg.w / 2, pg.m + h + 5.5, 'Cut along the middle and glue back to back. Turn it round at wake up time.', 3.4, { font: FONT, colour: SOFT }));
    pg.footer = () => {};
    pages.push(pg.svg());
  }
  if (want('pass')) {
    const pg = new Page(paper, 'Bedtime passes', { subtitle: 'Give one pass each night. It can be swapped for one quick thing after lights out. Then it is time to stay in bed!', noName: true });
    const { cw, ch } = cardGrid(pg, 4, 2);
    for (let i = 0; i < 4; i++) {
      const x = pg.left + (i % 2) * cw, y = pg.y + Math.floor(i / 2) * ch, c = PALETTE[(i + 3) % PALETTE.length];
      pg.add(`<rect x="${x + 3}" y="${y + 3}" width="${cw - 6}" height="${ch - 6}" rx="10" fill="#f5f2ff" stroke="${c}" stroke-width="1" stroke-dasharray="3 2"/>`);
      pg.add(emoji('🌙', x + cw / 2, y + 26, 24) + txt(x + cw / 2, y + 52, 'Bedtime pass', 9, { colour: c }));
      if (name) pg.add(txt(x + cw / 2, y + 62, `for ${name}`, 5.4, { font: FONT, colour: SOFT }));
      textLines(pg, wrap('Swap me for one: a drink, a hug, or a trip to the toilet.', 26), x + cw / 2, y + ch - 30, 4.8, { anchor: 'middle', font: FONT, weight: 700 });
    }
    pages.push(pg.svg());
  }
  if (want('chart')) {
    const pg = new Page(paper, name ? `${possessive(name)} stay in bed chart` : 'My stay in bed chart', { subtitle: 'Colour a moon every morning after a night of staying in bed. 14 moons earns a special treat!', noName: !!name });
    const { cw, ch } = cardGrid({ width: pg.width, room: pg.room - 30 }, 14, 4);
    for (let i = 0; i < 14; i++) {
      const x = pg.left + (i % 4) * cw, y = pg.y + Math.floor(i / 4) * ch, r = Math.min(cw, ch) * 0.32;
      pg.add(`<path d="M${x + cw / 2 + r * 0.3} ${y + ch / 2 - r} A${r} ${r} 0 1 0 ${x + cw / 2 + r * 0.3} ${y + ch / 2 + r} A${r * 0.78} ${r * 0.78} 0 1 1 ${x + cw / 2 + r * 0.3} ${y + ch / 2 - r} Z" fill="#fff8d6" stroke="${PALETTE[i % PALETTE.length]}" stroke-width="1.2"/>` + txt(x + cw / 2 - r * 0.1, y + ch / 2 + 2, i + 1, 5.4, { colour: PALETTE[i % PALETTE.length] }));
    }
    const by = pg.bottom - 22;
    pg.add(panel(pg.left, by, pg.width, 20, '#fff6e0', '#ffb938', 6) + pic(ART('present'), pg.left + 12, by + 10, 14) + txt(pg.left + 24, by + 12, 'My special treat will be', 5, { anchor: 'start', font: FONT }) + `<line x1="${pg.left + 82}" x2="${pg.right - 8}" y1="${by + 12.6}" y2="${by + 12.6}" stroke="#b9b3d6" stroke-width="0.4"/>`);
    pages.push(pg.svg());
  }
  if (want('routine')) {
    const r = packRun('routine', { routine: 'bedtime', layout: 'cards', name }, paper, +o.seed || 1);
    pages.push(...r.sheets);
  }
  return pages;
}

// ================================================================ food explorer
function makeFoods(o, paper) {
  const name = nameOf(o.name, '');
  const want = (k) => o[k] !== false;
  const pages = [];
  if (want('passport')) {
    const pg = new Page(paper, name ? `${possessive(name)} food explorer passport` : 'Food explorer passport', { subtitle: 'Brave explorers try new foods! Draw or write each food, then circle a face. Just one tiny taste counts.', noName: !!name });
    const { cw, ch } = cardGrid(pg, 12, 3);
    for (let i = 0; i < 12; i++) {
      const x = pg.left + (i % 3) * cw, y = pg.y + Math.floor(i / 3) * ch, c = PALETTE[i % PALETTE.length];
      pg.add(panel(x + 2, y + 2, cw - 4, ch - 4, '#fff', c, 7));
      pg.add(`<rect x="${x + 7}" y="${y + 7}" width="${cw - 14}" height="${ch * 0.5}" rx="5" fill="${TINTS[i % TINTS.length]}"/>` + txt(x + cw / 2, y + 7 + ch * 0.28, 'I tried', 4.4, { font: FONT, colour: SOFT }));
      pg.add(`<line x1="${x + 8}" x2="${x + cw - 8}" y1="${y + ch * 0.5 + 16}" y2="${y + ch * 0.5 + 16}" stroke="#c9c3e3" stroke-width="0.4"/>`);
      ['sad', 'calm', 'happy'].forEach((m, k) => pg.add(face(x + cw * (k + 1) / 4, y + ch - 11, 5, m, false)));
    }
    pages.push(pg.svg());
  }
  if (want('rainbow')) {
    const pg = new Page(paper, 'Eat the rainbow', { subtitle: 'Colour a box each time you eat a fruit or vegetable of that colour. Can you eat every colour this week?' });
    const rows = [['Red', '#ff4d4d', '🍓'], ['Orange', '#ff9f1c', '🥕'], ['Yellow', '#ffd23f', '🍌'], ['Green', '#3fbf60', '🥦'], ['Blue and purple', '#9b5de5', '🍇'], ['White and brown', '#b08968', '🍄']];
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'], lw = 48, cw = (pg.width - lw) / 7, rh = Math.min(30, (pg.room - 16) / rows.length);
    days.forEach((d, i) => pg.add(txt(pg.left + lw + cw * (i + 0.5), pg.y + 5, d, 4.6, { colour: SOFT })));
    rows.forEach(([nm, c, e], r) => {
      const y = pg.y + 9 + r * rh;
      pg.add(`<rect x="${pg.left}" y="${y + 1}" width="${lw - 3}" height="${rh - 2}" rx="5" fill="${c}"/>` + emoji(e, pg.left + 9, y + rh / 2, rh * 0.42) + txt(pg.left + 17, y + rh / 2 + 1.6, nm, fitFont(nm, 4.6, lw - 20, 0.5), { anchor: 'start', colour: '#fff' }));
      days.forEach((d, i) => pg.add(`<rect x="${pg.left + lw + cw * i + 1.5}" y="${y + 2}" width="${cw - 3}" height="${rh - 4}" rx="4" fill="#fff" stroke="${c}" stroke-width="0.8"/>`));
    });
    pages.push(pg.svg());
  }
  if (want('plate')) {
    const pg = new Page(paper, 'My favourite plate', { subtitle: 'Draw a meal you love. Try to include something from every part of the plate!' });
    const cx = pg.w / 2 - 6, cy = pg.y + 92, R = 72;
    pg.add(`<circle cx="${cx}" cy="${cy}" r="${R + 8}" fill="#fff" stroke="${INK}" stroke-width="0.9"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="#fff" stroke="#d9d4ec" stroke-width="0.6"/>`);
    [['Fruit and veg', '#3fbf60', -150, 30], ['Grains', '#ffb938', 30, 120], ['Protein', '#ff6b6b', 120, 210]].forEach(([t, c, a0, a1]) => {
      const r0 = (a0 * Math.PI) / 180, r1 = (a1 * Math.PI) / 180, mid = (r0 + r1) / 2;
      pg.add(`<path d="M${cx} ${cy} L${cx + Math.cos(r0) * R} ${cy + Math.sin(r0) * R} A${R} ${R} 0 0 1 ${cx + Math.cos(r1) * R} ${cy + Math.sin(r1) * R} Z" fill="none" stroke="${c}" stroke-width="0.8"/>`);
      pg.add(txt(cx + Math.cos(mid) * R * 0.72, cy + Math.sin(mid) * R * 0.72 + 2, t, 5, { colour: c }));
    });
    pg.add(emoji('🥛', cx + R + 16, cy - R + 14, 16));
    const ly = cy + R + 20;
    pg.add(txt(pg.left, ly, 'My meal is called', 5, { anchor: 'start', font: FONT }) + `<line x1="${pg.left + 48}" x2="${pg.right}" y1="${ly + 0.6}" y2="${ly + 0.6}" stroke="#b9b3d6" stroke-width="0.4"/>`);
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ social stories
const SOCIAL = {
  dentist: { title: 'Going to the dentist', pages: [['🦷', 'My name is {name}. Soon I am going to the dentist. A dentist is a friendly helper who looks after teeth.'], ['🚗', '{who} will come with me. We might wait in the waiting room for a little while. I can read a book while I wait.'], ['💺', 'When it is my turn, I sit in a big chair. The chair can go up and down and lean back. That is okay.'], ['💡', 'The dentist might shine a bright light. I open my mouth wide, like a lion!'], ['🪥', 'The dentist uses a little mirror to count my teeth. It might tickle. I can keep my hands still and breathe slowly.'], ['🌟', 'When it is finished, the dentist says well done. I did it! My teeth are strong and healthy.']] },
  doctor: { title: 'Going to the doctor', pages: [['🩺', 'My name is {name}. Soon I am going to see the doctor. Doctors help us stay well.'], ['⏳', '{who} will be with me. We might wait for a while, so I can bring a toy.'], ['👂', 'The doctor might look in my ears and my mouth with a little light. I say aaah!'], ['💓', 'The doctor might listen to my heart. The stethoscope feels cold, but it does not hurt.'], ['🤝', 'If I feel worried, I can hold a hand and say how I feel. Doctors are used to helping children.'], ['🌟', 'When it is finished, I can feel proud. I was brave today!']] },
  haircut: { title: 'Having a haircut', pages: [['✂️', 'My name is {name}. Today I am having a haircut. Hair grows all the time, so everyone needs a haircut sometimes.'], ['💺', 'I sit in a special chair. It might go up high so the hairdresser can reach. I might wear a cape.'], ['💦', 'The hairdresser might spray some water on my hair. It feels cool and a bit tickly.'], ['🔊', 'The scissors go snip, snip. Clippers might buzz. The sounds can be loud, but cutting hair does not hurt.'], ['🧸', 'I try to keep my head still. I can hold a toy or count slowly while I wait.'], ['🪞', 'When it is finished, I look in the mirror. I look great! I did it!']] },
  baby: { title: 'A new baby is coming', pages: [['👶', 'My name is {name}. Soon a new baby is coming to our family.'], ['😴', 'New babies sleep a lot and cry a lot. Crying is how babies talk. It does not mean they are cross with me.'], ['🍼', 'Grown-ups spend lots of time feeding and changing the baby. Sometimes I will need to wait.'], ['🤗', 'Even when the grown-ups are busy with the baby, they still love me just as much as before.'], ['🧸', 'I can be a great helper. I can pass a nappy, sing a song or show the baby my toys.'], ['💛', 'When I feel left out, I can say: I need a cuddle too. Our family is growing, and there is lots of love for everyone.']] },
  moving: { title: 'Moving to a new home', pages: [['🏠', 'My name is {name}. Soon my family is moving to a new home.'], ['📦', 'We will pack our things in boxes. My toys will come with us to the new home.'], ['🚚', 'On moving day, a big van will carry our boxes. It might be a busy, noisy day.'], ['🛏️', 'In the new home, I will have a place to sleep. It might feel strange at first, and that is okay.'], ['🗺️', 'We can explore the new place together and find new parks and new friends.'], ['💛', 'Home is wherever our family is. Soon the new house will feel like home.']] },
  flying: { title: 'Going on an aeroplane', pages: [['✈️', 'My name is {name}. Soon I am going on an aeroplane!'], ['🧳', 'At the airport, we give our big bags to the airport helpers. We keep a small bag with snacks and toys.'], ['🚶', 'We walk through a special gate. Helpers check our bags to keep everyone safe.'], ['💺', 'On the plane, I sit in my seat and wear a seat belt. It clicks when it is closed.'], ['☁️', 'The plane goes fast and then up into the sky. My ears might feel funny. Chewing or drinking can help.'], ['🌍', 'Soon we land somewhere new. I did it! Flying is an adventure.']] },
  sleepover: { title: 'My first sleepover', pages: [['🌙', 'My name is {name}. Soon I am having a sleepover.'], ['🎒', 'I will pack my pyjamas, my toothbrush and my favourite teddy.'], ['🍕', 'We might play games, eat dinner and watch a film. It will be fun!'], ['🛏️', 'At bedtime, I will sleep in a different bed. It might feel strange, and that is okay.'], ['📞', 'If I feel worried or miss home, I can tell a grown-up. They will help me feel better.'], ['🌟', 'In the morning, I can feel proud. I did a sleepover!']] },
};

function makeSocialStory(o, paper) {
  const st = SOCIAL[o.topic] || SOCIAL.dentist;
  const name = nameOf(o.name, '') || 'Mia';
  const who = String(o.who || '').trim().slice(0, 20) || 'My grown-up';
  const fill = (t) => t.replace(/\{name\}/g, name).replace(/\{who\}/g, who);
  const panels = [...st.pages.map(([e, t]) => ({ e, t: fill(t) })), { e: 'draw', t: 'Draw me doing it! How did I feel?' }];
  const pages = [];
  for (let p0 = 0; p0 < panels.length; p0 += 2) {
    const pg = new Page(paper, p0 ? '' : `${st.title}`, { bare: !!p0, subtitle: p0 ? '' : `A story for ${name}. Read it together a few times before the day.`, noName: true });
    const top = p0 ? pg.m : pg.y, h = (pg.bottom - top - 4) / 2;
    panels.slice(p0, p0 + 2).forEach((pn, k) => {
      const y = top + k * (h + 4), i = p0 + k, c = PALETTE[i % PALETTE.length];
      pg.add(panel(pg.left, y, pg.width, h, TINTS[i % TINTS.length], c, 10));
      if (pn.e === 'draw') {
        pg.add(`<rect x="${pg.left + 8}" y="${y + 8}" width="${pg.width - 16}" height="${h - 42}" rx="6" fill="#fff" stroke="${c}" stroke-width="0.6" stroke-dasharray="3 2"/>`);
        pg.add(txt(pg.w / 2, y + h - 26, pn.t, 7, { colour: c }));
        ['happy', 'proud', 'worried', 'calm'].forEach((m, q) => pg.add(face(pg.left + pg.width * (q + 1) / 5, y + h - 12, 6, m, false)));
      } else {
        pg.add(emoji(pn.e, pg.w / 2, y + h * 0.36, h * 0.38));
        textLines(pg, wrap(pn.t, 34), pg.w / 2, y + h * 0.68, 7.4, { anchor: 'middle', weight: 800, font: TITLE_FONT, colour: INK, lh: 1.35 });
        pg.add(txt(pg.right - 8, y + h - 5, i + 1, 4.4, { anchor: 'end', colour: c }));
      }
    });
    if (p0) pg.footer = () => {};
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ personalised storybook (Plus)
const STORYBOOKS = {
  star: { title: '{name} and the Lost Star', pages: [
    ['house', 'One night, {name} looked out of the window and saw a little star falling from the sky.'],
    ['owl', '"Hoo!" said a wise old owl. "That star is lost. Will you help it get home?"'],
    ['rocket', '{name} built a shiny rocket from boxes and paint. 3, 2, 1... Blast off!'],
    ['whale', 'They zoomed past the clouds and waved to a sleepy whale in the sea far below.'],
    ['robot', 'On the moon, a friendly robot pointed the way. "Beep boop! The star went that way!"'],
    ['unicorn', 'A sparkly unicorn gave {name} a ride all the way to the end of the rainbow.'],
    ['rainbow', 'There was the little star, crying. "I cannot find my way home!" {name} held it gently and flew up, up, up.'],
    ['teddy', 'Back in bed, {name} snuggled up with Teddy. Outside, a little star twinkled: "Thank you, {name}!"']] },
  party: { title: '{name}\'s Big Animal Party', pages: [
    ['cake', 'It was {name}\'s birthday, and {name} had a big idea: an animal party!'],
    ['elephant', 'Elephant came first, with a trunk full of balloons. Toot toot!'],
    ['giraffe', 'Giraffe hung the bunting up high, where nobody else could reach.'],
    ['penguin', 'Penguin brought ice cream and slid all the way across the floor. Wheee!'],
    ['frog', 'Frog jumped so high in the dancing game that everybody laughed.'],
    ['bee', 'Bee buzzed "Happy Birthday", and everyone joined in.'],
    ['turtle', 'Turtle arrived last, very slowly, with the best present of all: a card that said "You are the kindest friend".'],
    ['dog', '{name} gave everyone a great big hug. It was the best party ever!']] },
  sea: { title: '{name} Under the Sea', pages: [
    ['boat', '{name} sailed a little boat out onto the big blue sea.'],
    ['fish', 'Splash! A stripy fish popped up. "Come and see our secret garden!"'],
    ['octopus', '{name} put on a diving mask and met Octopus, who was juggling shells with eight arms.'],
    ['turtle', 'Old Turtle gave {name} a ride past waving seaweed and bright coral.'],
    ['whale', 'Then everything went dark. It was a giant whale, and she wanted to sing!'],
    ['penguin', 'The song was so beautiful that a penguin swam all the way from the ice to listen.'],
    ['rainbow', 'When it was time to go, the sun painted a rainbow over the water, and all the sea friends waved goodbye.'],
    ['house', 'That night, {name} fell asleep and dreamed of the sea. Swish, swash, goodnight.']] },
};

function makeStorybook(o, paper) {
  const bk = STORYBOOKS[o.story] || STORYBOOKS.star;
  const name = nameOf(o.name, '') || 'Mia';
  const from = String(o.from || '').trim().slice(0, 30);
  const fill = (t) => t.replace(/\{name\}/g, name);
  const title = fill(bk.title);
  const pages = [];
  // Cover
  // Cover design: Rainbow, Ocean, Garden or Space (the looks live in tools17.js).
  const lk = typeof lookOf === 'function' && o.look ? lookOf('namebook', o.look) : { ring: '#b06cff', tint: '#fffdf8', corners: [] };
  const cv = new Page(paper, '', { bare: true, tint: lk.tint });
  cv.add(`<rect x="${cv.left - 3}" y="${cv.m - 3}" width="${cv.width + 6}" height="${cv.bottom - cv.m + 3}" rx="12" fill="#fff" stroke="${lk.ring}" stroke-width="1.4"/><rect x="${cv.left}" y="${cv.m}" width="${cv.width}" height="${cv.bottom - cv.m - 3}" rx="9" fill="none" stroke="${lk.ring}" stroke-width="0.5" stroke-dasharray="2 1.6"/>`);
  lk.corners.forEach((e, i) => cv.add(emoji(e, i % 2 ? cv.right - 11 : cv.left + 11, i < 2 ? cv.m + 11 : cv.bottom - 12, 12)));
  let y = cv.m + 32;
  wrap(title, 18).forEach((l) => { bubbleText(cv, l, cv.w / 2, y, cv.width - 24, 20); y += 20; });
  const s = Math.min(cv.width - 30, cv.bottom - y - 34);
  cv.add(`<g transform="translate(${cv.w / 2 - s / 2} ${y + 4}) scale(${(s / 200).toFixed(4)})">${colouringArt(bk.pages[0][0])}</g>`);
  cv.add(txt(cv.w / 2, cv.bottom - 14, `A story starring ${name}`, 6, { colour: lk.ring }));
  cv.footer = () => {};
  pages.push(cv.svg());
  // Dedication
  const dd = new Page(paper, '', { bare: true, tint: '#fffdf8' });
  dd.add(pic(ART('heart'), dd.w / 2, dd.m + 80, 40));
  dd.add(txt(dd.w / 2, dd.m + 120, `This book was made for ${name}`, 9, { colour: INK }));
  if (from) dd.add(txt(dd.w / 2, dd.m + 134, `with love from ${from}`, 7, { colour: '#e0457b' }));
  else dd.add(txt(dd.w / 2, dd.m + 134, 'with love from', 7, { colour: '#e0457b' }) + `<line x1="${dd.w / 2 - 40}" x2="${dd.w / 2 + 40}" y1="${dd.m + 150}" y2="${dd.m + 150}" stroke="#b9b3d6" stroke-width="0.5"/>`);
  dd.add(txt(dd.w / 2, dd.bottom - 20, 'Colour the pictures as you read the story together.', 4.6, { font: FONT, colour: SOFT }));
  dd.footer = () => {};
  pages.push(dd.svg());
  bk.pages.forEach(([art, text], i) => {
    const pg = new Page(paper, '', { bare: true });
    const s2 = Math.min(pg.width - 20, (pg.bottom - pg.m) * 0.6);
    pg.add(`<rect x="${pg.left}" y="${pg.m}" width="${pg.width}" height="${s2 + 10}" rx="10" fill="#fff" stroke="#e2ddf2" stroke-width="0.6"/>`);
    pg.add(`<g transform="translate(${pg.w / 2 - s2 / 2} ${pg.m + 5}) scale(${(s2 / 200).toFixed(4)})">${colouringArt(art)}</g>`);
    const lines = wrap(fill(text), 30), fs = 8.4;
    const ty = pg.m + s2 + 16 + Math.max(0, (pg.bottom - pg.m - s2 - 30 - lines.length * fs * 1.4) / 2) + fs;
    textLines(pg, lines, pg.w / 2, ty, fs, { anchor: 'middle', weight: 800, font: TITLE_FONT, colour: INK, lh: 1.4 });
    pg.add(txt(pg.w / 2, pg.bottom + 1, i + 1, 4.6, { colour: '#b8b3cc' }));
    pg.footer = () => {};
    pages.push(pg.svg());
  });
  // The end
  const end = new Page(paper, '', { bare: true, tint: '#fffdf8' });
  bubbleText(end, 'The End', end.w / 2, end.m + 34, end.width - 40, 24);
  end.add(`<rect x="${end.left + 6}" y="${end.m + 48}" width="${end.width - 12}" height="${end.bottom - end.m - 70}" rx="10" fill="#fff" stroke="${lk.ring}" stroke-width="0.7" stroke-dasharray="3 2"/>` + txt(end.w / 2, end.m + 58, 'Draw your favourite part of the story', 5.4, { font: FONT, colour: SOFT }));
  end.add(txt(end.w / 2, end.bottom - 8, 'Made at printpals.web.app', 4, { font: FONT, colour: '#b8b3cc' }));
  end.footer = () => {};
  pages.push(end.svg());
  return pages;
}

// ================================================================ conversation cards
const TALK = {
  dinner: ['If you could have any superpower, what would it be?', 'What made you laugh today?', 'If animals could talk, which one would be the funniest?', 'What was the best thing that happened today?', 'If you could eat only one food forever, what would it be?', 'Who was kind to you today?',
    'What would you do if you were invisible for a day?', 'If you had a magic wand, what would you change?', 'What is something new you learned today?', 'Where in the world would you like to visit?', 'What would you name a brand new colour?', 'Which animal would you invite to dinner?'],
  car: ['I spy with my little eye... you choose!', 'Would you rather fly like a bird or swim like a fish?', 'Make up a song about where we are going.', 'Name 5 things that are red.', 'Would you rather have wheels or wings?', 'Which animal would be the silliest driver?',
    'Count all the blue cars you can see.', 'If this car could talk, what would it say?', 'What would you build with a million blocks?', 'Tell a story that starts: One day a giant...', 'Would you rather live in a treehouse or a castle?', 'What is your favourite sound?'],
  bedtime: ['What was the best part of your day?', 'What was a tricky part of your day?', 'What are you looking forward to tomorrow?', 'Who made you smile today?', 'What is one thing you are proud of?', 'If you could dream about anything, what would it be?',
    'What was the kindest thing you saw today?', 'When did you feel brave today?', 'What is something you want to learn?', 'What would you like to say thank you for?', 'What is your favourite thing about our family?', 'What should we do together this weekend?'],
  grandparents: ['What games did you play when you were little?', 'What was your favourite food as a child?', 'What was your home like when you were my age?', 'Who was your best friend?', 'What is the funniest thing that ever happened to you?', 'What songs did you sing when you were little?',
    'What was your first job?', 'What is your favourite memory of my mum or dad?', 'What did you want to be when you grew up?', 'What is the best advice anyone gave you?', 'What was school like for you?', 'What do you love doing with me?'],
};
const TALK_NAMES = { dinner: 'Dinner table questions', car: 'Car journey games', bedtime: 'Bedtime chats', grandparents: 'Questions for grandparents' };

function makeTalkCards(o, paper) {
  const sets = o.set === 'all' ? Object.keys(TALK) : [TALK[o.set] ? o.set : 'dinner'];
  return sets.map((k, si) => {
    const pg = new Page(paper, TALK_NAMES[k], { subtitle: 'Cut out the cards and keep them in a jar. Pick one and everyone answers!', noName: true });
    const { cw, ch } = cardGrid(pg, 12, 3);
    TALK[k].forEach((q, i) => {
      const x = pg.left + (i % 3) * cw, y = pg.y + Math.floor(i / 3) * ch, c = PALETTE[(i + si) % PALETTE.length];
      pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="7" fill="${TINTS[(i + si) % TINTS.length]}" stroke="#b9b3d6" stroke-width="0.4" stroke-dasharray="2 1.5"/>`);
      pg.add(`<circle cx="${x + cw / 2}" cy="${y + 12}" r="5" fill="${c}"/>` + txt(x + cw / 2, y + 14, '?', 6, { colour: '#fff' }));
      textLines(pg, wrap(q, 20), x + cw / 2, y + 26, 4.8, { anchor: 'middle', weight: 800, font: TITLE_FONT, colour: INK });
    });
    return pg.svg();
  });
}

// ================================================================ gratitude journal
function makeGratitude(o, paper) {
  const name = nameOf(o.name, '');
  const days = o.kind === 'week' ? 0 : 7;
  const pages = [];
  if (o.kind === 'week') {
    const pg = new Page(paper, name ? `${possessive(name)} thankful week` : 'My thankful week', { subtitle: 'Every day, write or draw one thing you are thankful for.', noName: !!name });
    const rh = (pg.room - 2) / 7;
    WEEKDAYS.forEach((d, i) => {
      const y = pg.y + i * rh, c = PALETTE[i % PALETTE.length];
      pg.add(panel(pg.left, y + 1, pg.width, rh - 2, TINTS[i % TINTS.length], c, 6) + txt(pg.left + 6, y + rh / 2 + 2, d, 6, { anchor: 'start', colour: c }));
      pg.add(`<rect x="${pg.left + 42}" y="${y + 4}" width="${rh - 8}" height="${rh - 8}" rx="4" fill="#fff" stroke="#d9d4ec" stroke-width="0.5"/>`);
      pg.add(`<line x1="${pg.left + 38 + rh}" x2="${pg.right - 6}" y1="${y + rh * 0.62}" y2="${y + rh * 0.62}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    });
    pages.push(pg.svg());
    return pages;
  }
  for (let d = 0; d < days; d++) {
    const pg = new Page(paper, name ? `${possessive(name)} happy journal` : 'My happy journal', { subtitle: `Day ${d + 1}. Date: ____________`, noName: !!name });
    const blocks = [['Three good things about today', 3, '#ff6b6b'], ['Today I was kind when', 2, '#3fbfa8'], ['Today I am proud that', 2, '#6c8cff']];
    let y = pg.y;
    blocks.forEach(([t, n, c], k) => {
      const h = 12 + n * 11;
      pg.add(panel(pg.left, y, pg.width, h, TINTS[k * 2], c, 7) + txt(pg.left + 6, y + 9, t, 5.6, { anchor: 'start', colour: c }));
      for (let l = 1; l <= n; l++) pg.add((n === 3 ? txt(pg.left + 7, y + 8 + l * 11, `${l}.`, 4.6, { anchor: 'start', colour: c }) : '') + `<line x1="${pg.left + 13}" x2="${pg.right - 6}" y1="${y + 9 + l * 11}" y2="${y + 9 + l * 11}" stroke="#c9c3e3" stroke-width="0.4"/>`);
      y += h + 5;
    });
    pg.add(txt(pg.left, y + 5, 'Today I felt', 5, { anchor: 'start', font: FONT }));
    ['happy', 'calm', 'proud', 'tired', 'sad', 'silly'].forEach((m, q) => pg.add(face(pg.left + 44 + q * 23, y + 3, 7, m, false)));
    y += 16;
    pg.add(`<rect x="${pg.left}" y="${y}" width="${pg.width}" height="${pg.bottom - y - 2}" rx="7" fill="#fff" stroke="#b06cff" stroke-width="0.6" stroke-dasharray="3 2"/>` + txt(pg.left + 5, y + 7, 'Draw the best part of your day', 4.4, { anchor: 'start', font: FONT, colour: SOFT }));
    pages.push(pg.svg());
  }
  return pages;
}

// ================================================================ potty training pack
const POTTY_STEPS = [['🩲', 'Pull down'], ['🚽', 'Sit on the potty'], ['💧', 'Wee or poo'], ['🧻', 'Wipe'], ['👖', 'Pull up'], ['🌊', 'Flush'], ['🧼', 'Wash my hands']];

function makePotty(o, paper) {
  const name = nameOf(o.name, '');
  const want = (k) => o[k] !== false;
  const pages = [];
  if (want('steps')) {
    const pg = new Page(paper, 'Using the potty', { subtitle: 'Follow the pictures, one step at a time. Point to each one as you go!', noName: true });
    const rh = (pg.room - 2) / POTTY_STEPS.length;
    POTTY_STEPS.forEach(([e, t], i) => {
      const y = pg.y + i * rh, c = PALETTE[i % PALETTE.length];
      pg.add(panel(pg.left, y + 1, pg.width, rh - 2, TINTS[i % TINTS.length], c, 8));
      pg.add(`<circle cx="${pg.left + 10}" cy="${y + rh / 2}" r="5.5" fill="${c}"/>` + txt(pg.left + 10, y + rh / 2 + 2.2, i + 1, 6, { colour: '#fff' }));
      pg.add(emoji(e, pg.left + 32, y + rh / 2, rh * 0.62) + txt(pg.left + 50, y + rh / 2 + 3, t, 9, { anchor: 'start', colour: INK }));
    });
    pages.push(pg.svg());
  }
  if (want('chart')) {
    const r = packRun('reward', { name, goal: 'I used the potty!', theme: o.theme || 'stars', spaces: '20', reward: '' }, paper, +o.seed || 1);
    pages.push(...r.sheets);
  }
  if (want('certificate')) pages.push(packCertificate(paper, name, 'You used the potty all by yourself! You are growing up so fast.'));
  return pages;
}

Object.assign(MAKERS, { calmkit: makeCalmKit, sleep: makeSleep, foods: makeFoods, socialstory: makeSocialStory, storybook: makeStorybook, talkcards: makeTalkCards, gratitude: makeGratitude, potty: makePotty });

;
// PrintPals batch 14: party invitations, countdown calendar, tooth brushing chart, family rules poster,
// babysitter info sheet, kitchen science and a letter writing kit. Two more Plus storybooks.

// ================================================================ party invitations
function makeInvites(o, paper) {
  const name = nameOf(o.name, '');
  const age = parseInt(o.age, 10);
  const bright = o.style !== 'colour';
  const theme = { balloons: ['balloon', 'present', 'cake', 'popper'], animals: ['lion', 'monkey', 'zebra', 'pig'], sweet: ['cupcake', 'donut', 'lolly', 'cookie'] }[o.theme] || ['balloon', 'present', 'cake', 'popper'];
  const lineArt = { balloons: ['cake', 'cake', 'cake', 'cake'], animals: ['elephant', 'giraffe', 'dog', 'cat'], sweet: ['icecream', 'cake', 'icecream', 'cake'] }[o.theme] || ['cake', 'cake', 'cake', 'cake'];
  const rows = [['Date', o.date], ['Time', o.time], ['Where', o.place], ['Please reply to', o.rsvp]];
  const pg = new Page(paper, '', { bare: true });
  const cw = pg.width / 2, ch = (pg.bottom - pg.m) / 2;
  for (let i = 0; i < 4; i++) {
    const x = pg.left + (i % 2) * cw, y = pg.m + Math.floor(i / 2) * ch, c = PALETTE[(i * 2) % PALETTE.length], cx = x + cw / 2;
    pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="10" fill="${bright ? TINTS[(i * 2) % TINTS.length] : '#fff'}" stroke="${bright ? c : INK}" stroke-width="1" stroke-dasharray="3 2"/>`);
    for (let s = 0; s < 7; s++) pg.add(`<path d="${starPath(x + 12 + s * (cw - 24) / 6, y + 9, 2.2, 0.45)}" fill="${bright ? PALETTE[s % PALETTE.length] : '#fff'}" stroke="${bright ? 'none' : INK}" stroke-width="0.4"/>`);
    if (bright) pg.add(pic(ART(theme[i]), cx, y + 30, 30));
    else pg.add(`<g transform="translate(${cx - 16} ${y + 14}) scale(0.16)">${colouringArt(lineArt[i])}</g>`);
    pg.add(txt(cx, y + 56, 'You\'re invited!', 9, { colour: bright ? c : INK }));
    const sub = name ? `to ${possessive(name)} ${age > 0 && age < 20 ? ordinal(age) + ' ' : ''}birthday party` : `to a birthday party`;
    pg.add(txt(cx, y + 64, sub, fitFont(sub, 5, cw - 14, 0.5), { font: FONT, colour: INK }));
    rows.forEach(([lab, val], k) => {
      const ry = y + 74 + k * 11, v = String(val || '').trim().slice(0, 34);
      pg.add(txt(x + 9, ry, lab, 3.8, { anchor: 'start', font: FONT, colour: SOFT }));
      pg.add(`<line x1="${x + 9 + lab.length * 2.2 + 3}" x2="${x + cw - 9}" y1="${ry + 0.6}" y2="${ry + 0.6}" stroke="#c9c3e3" stroke-width="0.4"/>`);
      if (v) pg.add(txt(x + 9 + lab.length * 2.2 + 5, ry - 0.6, v, fitFont(v, 4.4, cw - 30 - lab.length * 2.2, 0.5), { anchor: 'start', colour: INK }));
    });
  }
  pg.footer = () => {};
  return [pg.svg()];
}

// ================================================================ countdown calendar
const COUNT_OCCASIONS = { christmas: ['Christmas', '🎄'], eid: ['Eid', '🌙'], diwali: ['Diwali', '🪔'], birthday: ['my birthday', '🎂'], holiday: ['our holiday', '🏖️'], newyear: ['New Year', '🎆'] };
const COUNT_IDEAS = ['Make a card for someone special', 'Sing a song together', 'Read a story by torchlight', 'Do something kind for a neighbour', 'Draw a picture of the big day', 'Make paper decorations',
  'Have a dance party', 'Call someone you love', 'Write a thank you note', 'Build a blanket fort', 'Look at old family photos', 'Play a board game', 'Make a paper crown', 'Go for a walk and spot lights',
  'Help cook dinner', 'Give a toy to someone who needs it', 'Tell each other jokes', 'Play I spy', 'Make a gift for someone', 'Tidy a room as a surprise', 'Have a cosy film night', 'Bake something yummy',
  'Share three things you are thankful for', 'Get a big family hug'];

function makeCountdown(o, paper) {
  const rand = rng(+o.seed || 1);
  const custom = String(o.custom || '').trim().slice(0, 24);
  const [occ, e] = o.occasion === 'custom' && custom ? [custom, '⭐'] : (COUNT_OCCASIONS[o.occasion] || COUNT_OCCASIONS.christmas);
  const n = [7, 12, 24].includes(+o.days) ? +o.days : 24;
  const ideas = o.ideas !== false ? shuffle(COUNT_IDEAS, rand).slice(0, n) : [];
  const pg = new Page(paper, `Counting down to ${occ}!`, { subtitle: ideas.length ? 'Each day, do the little activity together, then colour the box.' : 'Colour a box every day. When they are all coloured, the big day is here!' });
  const cols = n === 7 ? 2 : n === 12 ? 3 : 4, rows = Math.ceil(n / cols);
  const cw = pg.width / cols, ch = (pg.room - 2) / rows, fs = n === 24 ? 4.2 : n === 12 ? 5.4 : 6.6;
  const order = shuffle([...Array(n).keys()], rand);
  order.forEach((d, i) => {
    const x = pg.left + (i % cols) * cw, y = pg.y + Math.floor(i / cols) * ch, c = PALETTE[d % PALETTE.length];
    pg.add(`<rect x="${x + 2}" y="${y + 2}" width="${cw - 4}" height="${ch - 4}" rx="6" fill="${TINTS[d % TINTS.length]}" stroke="${c}" stroke-width="0.9"/>`);
    pg.add(txt(x + 9, y + 12, d + 1, 9, { anchor: 'start', colour: c }));
    if (d === n - 1) pg.add(emoji(e, x + cw / 2, y + ch / 2 + 2, Math.min(cw, ch) * 0.4));
    else if (ideas.length) textLines(pg, wrap(ideas[d], Math.floor((cw - 10) / (fs * 0.55))), x + cw / 2, y + ch * 0.46, fs, { anchor: 'middle', font: FONT, weight: 700 });
    else pg.add(`<path d="${starPath(x + cw / 2, y + ch / 2 + 2, Math.min(cw, ch) * 0.22, 0.45)}" fill="#fff" stroke="${c}" stroke-width="0.8"/>`);
  });
  return [pg.svg()];
}

// ================================================================ tooth brushing chart
function makeTeeth(o, paper) {
  const name = nameOf(o.name, '');
  const pages = [];
  const pg = new Page(paper, name ? `${possessive(name)} tooth brushing chart` : 'My tooth brushing chart', { subtitle: 'Brush for two minutes every morning and every night. Colour a tooth each time!', noName: !!name });
  const cols = 4, rows = 8, cw = pg.width / cols;
  for (let c = 0; c < cols; c++) [['☀️', 0], ['🌙', 1]].forEach(([em, k]) => pg.add(emoji(em, pg.left + c * cw + 22 + k * (cw - 28) / 2 + (cw - 28) / 4, pg.y + 5, 7)));
  pg.y += 11;
  const ch = (pg.room - 2) / rows;
  for (let d = 0; d < 31; d++) {
    const x = pg.left + (d % cols) * cw, y = pg.y + Math.floor(d / cols) * ch, c = PALETTE[d % PALETTE.length];
    pg.add(`<rect x="${x + 1.5}" y="${y + 1.5}" width="${cw - 3}" height="${ch - 3}" rx="5" fill="${TINTS[d % TINTS.length]}"/>` + txt(x + 7, y + ch / 2 + 2, d + 1, 5.4, { colour: c }));
    [0, 1].forEach((k) => {
      const tx = x + 22 + k * (cw - 28) / 2 + (cw - 28) / 4;
      pg.add(`<path d="M${tx - 5} ${y + ch / 2 - 5} Q${tx - 6} ${y + ch / 2 - 9} ${tx - 2} ${y + ch / 2 - 8} Q${tx} ${y + ch / 2 - 7} ${tx + 2} ${y + ch / 2 - 8} Q${tx + 6} ${y + ch / 2 - 9} ${tx + 5} ${y + ch / 2 - 5} Q${tx + 4} ${y + ch / 2 + 2} ${tx + 3} ${y + ch / 2 + 7} Q${tx + 1} ${y + ch / 2 + 8} ${tx} ${y + ch / 2 + 2} Q${tx - 1} ${y + ch / 2 + 8} ${tx - 3} ${y + ch / 2 + 7} Q${tx - 4} ${y + ch / 2 + 2} ${tx - 5} ${y + ch / 2 - 5} Z" fill="#fff" stroke="${c}" stroke-width="0.7"/>`);
    });
  }
  const bx = pg.left + 3 * cw, by = pg.y + 7 * ch;
  pg.add(pic(ART('medal'), bx + cw / 2, by + ch / 2, ch * 0.8));
  pages.push(pg.svg());
  if (o.guide !== false) {
    const p2 = new Page(paper, 'How to brush my teeth', { subtitle: 'Sing a song or count slowly while you brush. Two minutes makes a super smile!' });
    const steps = [['🪥', 'A pea sized blob of toothpaste'], ['⬆️', 'Brush the top teeth in little circles'], ['⬇️', 'Brush the bottom teeth in little circles'], ['😁', 'Brush the fronts, the backs and the chewing tops'], ['👅', 'Give your tongue a gentle brush'], ['💦', 'Spit out the toothpaste. Do not rinse!'], ['⭐', 'Colour your chart. Super smile!']];
    const rh = (p2.room - 2) / steps.length;
    steps.forEach(([e2, t], i) => { const y = p2.y + i * rh, c = PALETTE[i % PALETTE.length]; p2.add(panel(p2.left, y + 1, p2.width, rh - 2, TINTS[i % TINTS.length], c, 8) + `<circle cx="${p2.left + 10}" cy="${y + rh / 2}" r="5.5" fill="${c}"/>` + txt(p2.left + 10, y + rh / 2 + 2.2, i + 1, 6, { colour: '#fff' }) + emoji(e2, p2.left + 30, y + rh / 2, rh * 0.55) + txt(p2.left + 46, y + rh / 2 + 2.4, t, fitFont(t, 7, p2.width - 52, 0.5), { anchor: 'start', colour: INK })); });
    pages.push(p2.svg());
  }
  return pages;
}

// ================================================================ family rules poster
const FAMILY_RULES = ['We say please and thank you', 'We use kind words', 'We tell the truth', 'We help each other', 'We say sorry and forgive', 'We try new things', 'We share and take turns', 'We laugh a lot', 'We hug often', 'We love each other, always'];

function makeFamilyRules(o, paper) {
  const fam = String(o.family || '').trim().slice(0, 24);
  const rules = (listOf(o.rules, 12).length ? listOf(o.rules, 12) : FAMILY_RULES).map((r) => r.slice(0, 44));
  const bright = o.style !== 'colour';
  const pg = new Page(paper, '', { bare: true, tint: bright ? '#fffdf8' : '#fff' });
  pg.add(`<rect x="${pg.left - 3}" y="${pg.m - 3}" width="${pg.width + 6}" height="${pg.bottom - pg.m + 3}" rx="14" fill="none" stroke="${bright ? '#ff7eb6' : INK}" stroke-width="1.4"/>`);
  ['heart', 'star', 'star', 'heart'].forEach((a, i) => pg.add(bright ? pic(ART(a), i % 2 ? pg.right - 9 : pg.left + 9, i < 2 ? pg.m + 9 : pg.bottom - 11, 13) : `<path d="${starPath(i % 2 ? pg.right - 9 : pg.left + 9, i < 2 ? pg.m + 9 : pg.bottom - 11, 5, 0.45)}" fill="#fff" stroke="${INK}" stroke-width="0.6"/>`));
  pg.add(txt(pg.w / 2, pg.m + 24, fam ? `The ${fam} family` : 'In our family', 11, { colour: bright ? '#8a3fd1' : INK }));
  bubbleText(pg, fam ? 'Rules' : 'We...', pg.w / 2, pg.m + 50, pg.width - 60, 26);
  const top = pg.m + 62, rh = Math.min(22, (pg.bottom - 18 - top) / rules.length);
  rules.forEach((r, i) => {
    const y = top + i * rh, c = PALETTE[i % PALETTE.length];
    pg.add(bright ? `<path d="${starPath(pg.left + 18, y + rh / 2, 4.2, 0.45)}" fill="${c}"/>` : `<path d="${starPath(pg.left + 18, y + rh / 2, 4.2, 0.45)}" fill="#fff" stroke="${INK}" stroke-width="0.6"/>`);
    pg.add(txt(pg.left + 28, y + rh / 2 + 2.4, r, fitFont(r, 8, pg.width - 40, 0.5), { anchor: 'start', colour: bright ? c : INK }));
  });
  pg.footer = () => {};
  return [pg.svg()];
}

// ================================================================ babysitter and grandparent info sheet
function makeSitter(o, paper) {
  const name = nameOf(o.name, '');
  const v = (k) => String(o[k] || '').trim().slice(0, 60);
  const pg = new Page(paper, name ? `Looking after ${name}` : 'Looking after our child', { subtitle: 'Everything a babysitter, grandparent or friend needs to know. Keep it on the fridge.', noName: true });
  const blocks = [
    ['Allergies and medicines', v('allergies'), '#ff6b6b', 2], ['Bedtime and naps', v('bedtime'), '#6c8cff', 2], ['Food they love (and will not eat)', v('food'), '#ffb938', 2],
    ['What calms them when they are upset', v('calm'), '#3fbfa8', 2], ['Favourite games, toys and shows', v('fun'), '#b06cff', 2], ['House rules', v('rules'), '#ff7eb6', 2],
  ];
  const cw = pg.width / 2, bh = (pg.room - 70) / 3;
  blocks.forEach(([t, val, c, n], i) => {
    const x = pg.left + (i % 2) * cw, y = pg.y + Math.floor(i / 2) * bh;
    pg.add(panel(x + 1.5, y + 1.5, cw - 3, bh - 3, '#fff', c, 7) + txt(x + 7, y + 10, t, fitFont(t, 5, cw - 14, 0.5), { anchor: 'start', colour: c }));
    if (val) textLines(pg, wrap(val, 30), x + 7, y + 20, 5, { weight: 700 });
    else for (let l = 1; l <= 3; l++) pg.add(`<line x1="${x + 7}" x2="${x + cw - 7}" y1="${y + 12 + l * (bh - 18) / 3.4}" y2="${y + 12 + l * (bh - 18) / 3.4}" stroke="#c9c3e3" stroke-width="0.4"/>`);
  });
  const ey = pg.y + 3 * bh + 2;
  pg.add(panel(pg.left, ey, pg.width, pg.bottom - ey - 2, '#fff0f0', '#ff4d4d', 8) + txt(pg.left + 7, ey + 10, 'In an emergency', 6.4, { anchor: 'start', colour: '#e03c3c' }) + emoji('📞', pg.right - 12, ey + 9, 9));
  [['Parent', 'Phone'], ['Second contact', 'Phone'], ['Doctor', 'Phone'], ['Our address', '']].forEach(([a, b], i) => {
    const y = ey + 22 + i * 11;
    pg.add(txt(pg.left + 7, y, a, 4.6, { anchor: 'start', font: FONT, colour: SOFT }) + `<line x1="${pg.left + 38}" x2="${b ? pg.left + pg.width * 0.58 : pg.right - 7}" y1="${y + 0.6}" y2="${y + 0.6}" stroke="#b9b3d6" stroke-width="0.4"/>`);
    if (b) pg.add(txt(pg.left + pg.width * 0.61, y, b, 4.6, { anchor: 'start', font: FONT, colour: SOFT }) + `<line x1="${pg.left + pg.width * 0.61 + 13}" x2="${pg.right - 7}" y1="${y + 0.6}" y2="${y + 0.6}" stroke="#b9b3d6" stroke-width="0.4"/>`);
  });
  return [pg.svg()];
}

// ================================================================ kitchen science
const SCIENCE = {
  float: { title: 'Sink or float?', need: [['🥣', 'A big bowl of water'], ['🍎', 'An apple'], ['🥄', 'A spoon'], ['🍃', 'A leaf'], ['🪙', 'A coin'], ['🧸', 'A small toy']], steps: ['Fill the bowl with water.', 'Before each one, guess: will it sink or float?', 'Gently put it in the water and watch.', 'Tick what really happened.'], why: 'Heavy things for their size sink. Things with lots of air inside, like an apple, float.', table: ['An apple', 'A spoon', 'A leaf', 'A coin', 'A small toy', 'Something you choose'] },
  raisins: { title: 'Dancing raisins', need: [['🥛', 'A clear glass'], ['🫧', 'Fizzy water'], ['🍇', 'A few raisins']], steps: ['Fill the glass with fizzy water.', 'Drop in six raisins.', 'Watch closely for one minute.', 'Count how many raisins dance up and down!'], why: 'Bubbles stick to the wrinkly raisins and lift them up. At the top the bubbles pop, and the raisins sink again.' },
  walking: { title: 'Walking water', need: [['🥛', 'Three clear cups'], ['💧', 'Water'], ['🎨', 'Red and blue food colouring'], ['🧻', 'Kitchen roll']], steps: ['Put the cups in a row. Half fill the two end cups with water.', 'Add red colouring to one end cup and blue to the other.', 'Fold two strips of kitchen roll. Make bridges from each end cup to the middle cup.', 'Wait and watch. Check again after an hour!'], why: 'Water climbs up the tiny gaps in the paper. The colours meet in the middle cup and mix to make purple.' },
  volcano: { title: 'Fizzing volcano', need: [['🥛', 'A cup on a tray'], ['🧂', '2 spoons of bicarbonate of soda'], ['🍶', 'Some vinegar'], ['🧴', 'A squirt of washing up liquid'], ['🎨', 'Red food colouring']], steps: ['Put the cup on a tray. A grown-up helps with this one!', 'Add the bicarbonate of soda, washing up liquid and colouring.', 'Pour in the vinegar.', 'Stand back and watch it fizz!'], why: 'Vinegar and bicarbonate of soda make a gas called carbon dioxide. The bubbles push the foam up and over, like a volcano.' },
  pepper: { title: 'Magic pepper', need: [['🍽️', 'A plate'], ['💧', 'Water'], ['🧂', 'Ground pepper'], ['🧼', 'A little soap or washing up liquid']], steps: ['Pour a little water onto the plate.', 'Sprinkle pepper all over the water.', 'Put a dot of soap on your fingertip.', 'Touch the middle of the water and watch!'], why: 'Soap breaks the stretchy skin on top of the water, so the pepper rushes away to the edges.' },
  ice: { title: 'Ice melting race', need: [['🧊', 'Three ice cubes'], ['🍽️', 'Three plates'], ['🧂', 'Salt'], ['🍬', 'Sugar']], steps: ['Put one ice cube on each plate.', 'Sprinkle salt on one, sugar on another, and nothing on the third.', 'Guess which will melt first.', 'Check every five minutes. Which one won?'], why: 'Salt makes ice melt faster. That is why salt is put on icy roads in winter.' },
};

function makeScience(o, paper) {
  const ex = SCIENCE[o.experiment] || SCIENCE.float;
  const pg = new Page(paper, ex.title, { subtitle: 'A kitchen science experiment. Always do it with a grown-up!' });
  const cw = pg.width * 0.42;
  pg.add(panel(pg.left, pg.y, cw, ex.need.length * 11 + 14, '#fff6e0', '#ffb938', 7) + txt(pg.left + 6, pg.y + 9, 'You will need', 5.6, { anchor: 'start', colour: '#e08a00' }));
  ex.need.forEach(([e, t], i) => pg.add(emoji(e, pg.left + 11, pg.y + 18 + i * 11, 7) + txt(pg.left + 19, pg.y + 19.6 + i * 11, t, fitFont(t, 4.4, cw - 24, 0.5), { anchor: 'start', font: FONT })));
  const sx = pg.left + cw + 6, sw = pg.width - cw - 6;
  pg.add(txt(sx, pg.y + 9, 'What to do', 5.6, { anchor: 'start', colour: '#3a64d8' }));
  let sy = pg.y + 17;
  ex.steps.forEach((s, i) => {
    pg.add(`<circle cx="${sx + 3.5}" cy="${sy - 1.5}" r="3.2" fill="${PALETTE[i % PALETTE.length]}"/>` + txt(sx + 3.5, sy, i + 1, 3.8, { colour: '#fff' }));
    sy = textLines(pg, wrap(s, Math.floor((sw - 10) / 2.25)), sx + 9, sy, 4.4, { font: FONT, weight: 700 }) + 2;
  });
  pg.y = Math.max(pg.y + ex.need.length * 11 + 20, sy + 4);
  if (ex.table) {
    const rh = 10, cols = [0.46, 0.27, 0.27];
    [['Object', 'I think', 'It did']].concat(ex.table.map((t) => [t, 'sink / float', 'sink / float'])).forEach((row, r) => {
      let x = pg.left;
      row.forEach((cell, k) => { const w = pg.width * cols[k]; pg.add(`<rect x="${x}" y="${pg.y + r * rh}" width="${w}" height="${rh}" fill="${r ? '#fff' : '#eef2ff'}" stroke="#c9c3e3" stroke-width="0.4"/>` + txt(x + (k ? w / 2 : 4), pg.y + r * rh + 6.6, cell, 4.2, { anchor: k ? 'middle' : 'start', font: FONT, weight: r ? 700 : 800, colour: r && k ? SOFT : INK })); x += w; });
    });
    pg.y += (ex.table.length + 1) * rh + 6;
  } else {
    pg.add(panel(pg.left, pg.y, pg.width, 30, '#e8f8f4', '#3fbfa8', 7) + txt(pg.left + 6, pg.y + 9, 'I think this will happen', 5.4, { anchor: 'start', colour: '#2e9d85' }));
    for (let l = 1; l <= 2; l++) pg.add(`<line x1="${pg.left + 6}" x2="${pg.right - 6}" y1="${pg.y + 9 + l * 9}" y2="${pg.y + 9 + l * 9}" stroke="#c9c3e3" stroke-width="0.4"/>`);
    pg.y += 36;
  }
  const bh = pg.room - 26;
  pg.add(`<rect x="${pg.left}" y="${pg.y}" width="${pg.width}" height="${bh}" rx="7" fill="#fff" stroke="#b06cff" stroke-width="0.7" stroke-dasharray="3 2"/>` + txt(pg.left + 6, pg.y + 8, 'What happened? Draw it!', 5.2, { anchor: 'start', colour: '#8a3fd1' }));
  pg.y += bh + 4;
  textLines(pg, wrap(`For grown-ups: ${ex.why}`, 96), pg.left, pg.y + 4, 3.8, { font: FONT, weight: 600, colour: SOFT });
  return [pg.svg()];
}

// ================================================================ letter writing kit
function makeLetterKit(o, paper) {
  const name = nameOf(o.name, '');
  const to = String(o.to || '').trim().slice(0, 24);
  const art = ['sun', 'rainbow', 'heart', 'star', 'balloon', 'tulip'];
  const pages = [];
  const pg = new Page(paper, '', { bare: true, tint: '#fffdf8' });
  pg.add(`<rect x="${pg.left - 3}" y="${pg.m - 3}" width="${pg.width + 6}" height="${pg.bottom - pg.m + 3}" rx="12" fill="#fff" stroke="#ffb938" stroke-width="1"/>`);
  art.forEach((a, i) => pg.add(pic(ART(a), pg.left + 12 + i * (pg.width - 24) / 5, pg.m + 11, 13)));
  pg.add(txt(pg.left + 8, pg.m + 34, to ? `Dear ${to},` : 'Dear', 9, { anchor: 'start', colour: '#e0457b' }));
  if (!to) pg.add(`<line x1="${pg.left + 32}" x2="${pg.left + 110}" y1="${pg.m + 34.6}" y2="${pg.m + 34.6}" stroke="#b9b3d6" stroke-width="0.5"/>`);
  const ly0 = pg.m + 48, lh = 12, n = Math.floor((pg.bottom - 40 - ly0) / lh);
  for (let l = 0; l < n; l++) pg.add(`<line x1="${pg.left + 8}" x2="${pg.right - 8}" y1="${ly0 + l * lh}" y2="${ly0 + l * lh}" stroke="#d9d4ec" stroke-width="0.45"/>`);
  pg.add(txt(pg.right - 10, pg.bottom - 22, name ? `Love from ${name}` : 'Love from', 8, { anchor: 'end', colour: '#e0457b' }));
  if (!name) pg.add(`<line x1="${pg.right - 70}" x2="${pg.right - 10}" y1="${pg.bottom - 10}" y2="${pg.bottom - 10}" stroke="#b9b3d6" stroke-width="0.5"/>`);
  pg.footer = () => {};
  pages.push(pg.svg());
  if (o.envelope !== false) {
    const p2 = new Page(paper, 'Fold your own envelope', { subtitle: 'Cut around the outside. Fold the side flaps in, then the bottom up, and glue. Fold the top down to close it.', noName: true });
    const W = 120, H = 80, cx = p2.w / 2, top = p2.y + 42, x0 = cx - W / 2;
    const d = `M${x0} ${top} L${cx} ${top - 38} L${x0 + W} ${top} L${x0 + W + 30} ${top + 10} L${x0 + W + 30} ${top + H - 10} L${x0 + W} ${top + H} L${cx + 48} ${top + H + 42} L${cx - 48} ${top + H + 42} L${x0} ${top + H} L${x0 - 30} ${top + H - 10} L${x0 - 30} ${top + 10} Z`;
    p2.add(`<path d="${d}" fill="#fff6e0" stroke="${INK}" stroke-width="0.7" stroke-dasharray="2.5 1.6"/>`);
    p2.add(`<rect x="${x0}" y="${top}" width="${W}" height="${H}" fill="#fff" stroke="#b9b3d6" stroke-width="0.5"/>`);
    p2.add(`<rect x="${x0 + W - 24}" y="${top + 5}" width="19" height="23" rx="1.5" fill="#fff" stroke="#ff7eb6" stroke-width="0.7" stroke-dasharray="1.4 1"/>` + txt(x0 + W - 14.5, top + 18, 'stamp', 3.4, { font: FONT, colour: SOFT }));
    p2.add(txt(x0 + 8, top + 40, 'To:', 5, { anchor: 'start', colour: INK }));
    for (let l = 0; l < 3; l++) p2.add(`<line x1="${x0 + 18}" x2="${x0 + W - 10}" y1="${top + 40 + l * 11}" y2="${top + 40 + l * 11}" stroke="#c9c3e3" stroke-width="0.45"/>`);
    if (to) p2.add(txt(x0 + 20, top + 39, to, 6, { anchor: 'start', colour: '#e0457b' }));
    p2.add(txt(cx, top - 14, 'top flap', 3.6, { font: FONT, colour: SOFT }) + txt(cx, top + H + 26, 'bottom flap (glue)', 3.6, { font: FONT, colour: SOFT }) + txt(x0 - 15, top + H / 2, 'glue', 3.6, { font: FONT, colour: SOFT }) + txt(x0 + W + 15, top + H / 2, 'glue', 3.6, { font: FONT, colour: SOFT }));
    const gy = top + H + 50;
    p2.add(panel(p2.left, gy, p2.width, p2.bottom - gy - 2, '#eef2ff', '#6c8cff', 8) + txt(p2.left + 7, gy + 10, 'How to write a letter', 6, { anchor: 'start', colour: '#3a64d8' }));
    ['Start with "Dear" and their name.', 'Say hello and ask how they are.', 'Tell them your news: something fun you did.', 'Ask them a question about their day.', 'Finish with "Love from" and your name. Add a drawing!'].forEach((t, i) => p2.add(`<circle cx="${p2.left + 10}" cy="${gy + 19 + i * 8.5}" r="3" fill="${PALETTE[i]}"/>` + txt(p2.left + 10, gy + 20.4 + i * 8.5, i + 1, 3.6, { colour: '#fff' }) + txt(p2.left + 17, gy + 20.6 + i * 8.5, t, 4.6, { anchor: 'start', font: FONT })));
    pages.push(p2.svg());
  }
  return pages;
}

